/// Durable session lifecycle reconstructed by replay.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SessionLifecycle {
    /// Ready to process work.
    Active,
    /// Persisted without active execution.
    Suspended,
    /// Successfully finished.
    Completed,
    /// Terminated by a business failure.
    Failed,
    /// Explicitly cancelled.
    Cancelled,
    /// Retained but excluded from ordinary active listings.
    Archived,
}

/// Durable approval state.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ApprovalState {
    /// Awaiting a user/supervisor decision.
    Pending,
    /// Approved exactly once.
    Approved,
    /// Denied exactly once.
    Denied,
}

/// Exact canonical operation linked to a durable approval.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum ApprovalSubject {
    /// One exact runtime-owned automatic-memory write.
    NativeAutomaticMemoryWrite {
        /// Canonical automatic-memory outbox identity.
        write_id: String,
        /// Digest of the exact consequential action.
        action_digest: ContentHash,
    },
    /// One exact plugin-provided automatic-memory write.
    PluginAutomaticMemoryWrite {
        /// Canonical automatic-memory outbox identity.
        write_id: String,
        /// Digest-backed isolated invocation identity.
        invocation_id: String,
        /// Digest of the exact isolated invocation.
        invocation_digest: ContentHash,
        /// Digest of the exact consequential action.
        action_digest: ContentHash,
    },
    /// One exact policy stage of a plugin context operation.
    PluginContextOperation {
        /// Digest-backed isolated invocation identity.
        invocation_id: String,
        /// Digest of the exact isolated invocation.
        invocation_digest: ContentHash,
        /// Whether policy authorizes invocation or proposal application.
        stage: PluginContextApprovalStage,
        /// Digest of the exact consequential action.
        action_digest: ContentHash,
        /// Completed proposal hash for application approval.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        proposal_hash: Option<ContentHash>,
        /// Exact replacement hash for application approval.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        replacement_hash: Option<ContentHash>,
    },
}

/// Policy stage linked to a plugin context-operation approval.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum PluginContextApprovalStage {
    /// Approval to cross the plugin-host invocation boundary.
    Invocation,
    /// Approval to apply a runtime-validated replacement proposal.
    Application,
}

/// Approval reconstructed from canonical events.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct ApprovalRecord {
    /// Opaque continuation.
    pub continuation_id: ContinuationId,
    /// Redacted action summary.
    pub action_summary: String,
    /// Exact linked operation, absent on legacy approvals.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub subject: Option<ApprovalSubject>,
    /// Current decision.
    pub state: ApprovalState,
    /// Sequence at which approval became pending.
    pub requested_at: Sequence,
    /// Sequence at which it became terminal.
    pub resolved_at: Option<Sequence>,
}

/// Provenance class for the immutable style selected by a session.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SessionStyleSource {
    /// Shipped with the runtime.
    BuiltIn,
    /// Loaded from the configured user style directory.
    User,
    /// Loaded from the configured project style directory.
    Project,
    /// Supplied by a validated plugin package.
    Plugin,
    /// Supplied directly by a calling client.
    Inline,
}

