/// Deterministic compilation provenance for an immutable execution plan.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct SessionExecutionPlanCompilation {
    /// Version of the runtime-owned execution-plan schema/compiler.
    pub compiler: String,
    /// Exact compiled style descriptor hash.
    pub compiled_style_hash: ContentHash,
    /// Compatibility-bound style compiler cache key.
    pub compiled_cache_key: ContentHash,
    /// Runtime API version against which executors were resolved.
    pub runtime_api_version: String,
}

/// Runtime-supported execution-plan compiler generation.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ExecutionPlanCompilerGeneration {
    /// Original exact executor-resolution plan.
    V2,
    /// Dispatch-mode-aware exact executor-resolution plan.
    V3,
}

/// Exact compiler identity retained by existing generation-2 sessions.
pub(crate) const EXECUTION_PLAN_COMPILER_V2: &str = "agentmod-runtime-node-plan@2";
/// Compiler identity used for newly compiled generic execution plans.
///
/// Exact built-in `1.1.0` compatibility descriptors retain generation two so
/// their immutable historical adapter and recovery contract remains usable.
pub(crate) const EXECUTION_PLAN_COMPILER_V3: &str = "agentmod-runtime-node-plan@3";

impl SessionExecutionPlanCompilation {
    /// Classifies an exact supported compiler identity without accepting an
    /// unknown future generation.
    pub(crate) fn compiler_generation(&self) -> Option<ExecutionPlanCompilerGeneration> {
        match self.compiler.as_str() {
            EXECUTION_PLAN_COMPILER_V2 => Some(ExecutionPlanCompilerGeneration::V2),
            EXECUTION_PLAN_COMPILER_V3 => Some(ExecutionPlanCompilerGeneration::V3),
            _ => None,
        }
    }
}

/// Immutable exact execution plan retained by a session-style binding.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct SessionExecutionPlan {
    /// Hash of the complete live registry used for initial resolution.
    pub registry_hash: ContentHash,
    /// Deterministic compiler provenance.
    pub compilation: SessionExecutionPlanCompilation,
    /// Exact per-node resolutions, sorted by node ID.
    pub nodes: Vec<SessionNodeExecutorResolution>,
}

/// Immutable per-session MCP activation binding retained in canonical history.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct SessionMcpBinding {
    /// Binding schema generation.
    pub schema_version: u16,
    /// Hash of the exact ordered declarations, including secret values.
    pub declaration_hash: ContentHash,
    /// Dependency-owned encrypted configuration reference.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub configuration_reference: Option<String>,
    /// Ordered sanitized server declarations.
    pub servers: Vec<SessionMcpServerBinding>,
}

impl Default for SessionMcpBinding {
    fn default() -> Self {
        Self {
            schema_version: 1,
            declaration_hash: ContentHash::digest(b"agentmod.session-mcp.empty@1"),
            configuration_reference: None,
            servers: Vec::new(),
        }
    }
}

