/// Runtime-owned plugin context operation family.
#[derive(Clone, Copy, Debug, Deserialize, Eq, Ord, PartialEq, PartialOrd, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum PluginContextOperationKind {
    /// Retrieve typed memory through an exact immutable plugin provider.
    MemoryRetrieve,
    /// Compact provider-visible context through an exact immutable plugin
    /// compactor.
    Compaction,
}

impl PluginContextOperationKind {
    /// Stable wire label used in IDs and policy proposals.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::MemoryRetrieve => "memory_retrieve",
            Self::Compaction => "compaction",
        }
    }
}

/// Bounded runtime-owned request sent to one plugin context implementation.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(tag = "kind", content = "request", rename_all = "snake_case")]
pub enum PluginContextOperationRequest {
    /// Exact memory retrieval query and hard result limits.
    MemoryRetrieve {
        /// Runtime-constructed query.
        query: String,
        /// Exact normalized scopes.
        scopes: Vec<String>,
        /// Hard item limit.
        max_items: u32,
        /// Hard serialized injection limit.
        max_injected_bytes: u64,
    },
    /// Exact provider projection and preservation contract.
    Compaction {
        /// Current canonical provider projection.
        projection: Vec<ConversationEntry>,
        /// Hash of the exact projection.
        projection_hash: ContentHash,
        /// Provider-independent token estimate.
        estimated_tokens: u64,
        /// Exact serialized projection bytes.
        serialized_bytes: u64,
        /// Hard post-compaction token ceiling.
        max_projection_tokens: u64,
        /// Stable required preservation labels.
        preservation_requirements: Vec<String>,
        /// Ordered immutable artifact references that must survive.
        artifact_references: Vec<String>,
        /// Ordered canonical non-artifact references that must survive.
        references: Vec<String>,
    },
}

impl PluginContextOperationRequest {
    const fn kind(&self) -> PluginContextOperationKind {
        match self {
            Self::MemoryRetrieve { .. } => PluginContextOperationKind::MemoryRetrieve,
            Self::Compaction { .. } => PluginContextOperationKind::Compaction,
        }
    }
}

/// Runtime-validated proposal recovered from one sealed plugin receipt.
///
/// This is deliberately an application proposal, never an instruction to
/// mutate canonical state. Runtime policy separately approves and applies the
/// exact replacement.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(tag = "kind", content = "proposal", rename_all = "snake_case")]
pub enum PluginContextOperationProposal {
    /// Provider projection containing runtime-validated retrieved-memory
    /// entries and all pre-existing required context.
    MemoryRetrieve {
        /// Exact bounded replacement proposed for application.
        replacement: Vec<ConversationEntry>,
        /// Exact IDs of entries introduced by this operation.
        retrieved_entry_ids: Vec<ConversationEntryId>,
    },
    /// Runtime-validated compacted provider projection.
    Compaction {
        /// Exact bounded replacement proposed for application.
        replacement: Vec<ConversationEntry>,
        /// Ordered immutable artifact references proven preserved.
        preserved_artifact_references: Vec<String>,
        /// Ordered canonical non-artifact references proven preserved.
        preserved_references: Vec<String>,
    },
}

impl PluginContextOperationProposal {
    const fn kind(&self) -> PluginContextOperationKind {
        match self {
            Self::MemoryRetrieve { .. } => PluginContextOperationKind::MemoryRetrieve,
            Self::Compaction { .. } => PluginContextOperationKind::Compaction,
        }
    }

    fn replacement(&self) -> &[ConversationEntry] {
        match self {
            Self::MemoryRetrieve { replacement, .. } | Self::Compaction { replacement, .. } => {
                replacement
            }
        }
    }
}

