pub struct ParallelBranchRegionBinding {
    /// Stable graph-owned region identity.
    pub region_id: String,
    /// Exact runtime and configured-member identity.
    pub member: ParallelMemberBinding,
    /// Every compiled node owned by this branch before the join.
    pub node_ids: BTreeSet<String>,
    /// Canonical variables the region may write.
    #[serde(default)]
    pub write_variables: BTreeSet<String>,
    /// Canonical workspace resources the region may write.
    #[serde(default)]
    pub workspace_resources: BTreeSet<String>,
    /// Exact canonical variable versions observed before fan-out.
    #[serde(default)]
    pub variable_base_versions: BTreeMap<String, u64>,
    /// Exact canonical workspace-resource versions observed before fan-out.
    #[serde(default)]
    pub workspace_base_versions: BTreeMap<String, u64>,
}

/// Replay-owned control position for one nested parallel branch.
///
/// This is intentionally separate from [`StyleExecutionControlState`]; legacy
/// root node events therefore remain unambiguous.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(tag = "state", content = "detail", rename_all = "snake_case")]
pub enum ParallelBranchControlState {
    /// The member is waiting in the bounded fan-out queue.
    Queued,
    /// A stable dispatch is canonical but no branch node has acknowledged it.
    Dispatched,
    /// The next legal nested event is entry into this compiled node.
    ReadyForEntry(ParallelBranchNodeCursor),
    /// One exact nested node is active.
    Active(ParallelBranchNodeEnteredEvent),
    /// A nested node completed and awaits a compiled transition.
    AwaitingTransition(ParallelBranchNodeCompletedEvent),
    /// A transition is selected and its destination has not been entered.
    AwaitingDestinationEntry(ParallelBranchTransitionSelectedEvent),
    /// A nested node failed and requires an explicit terminal event.
    AwaitingFailure(ParallelBranchNodeFailedEvent),
    /// The member reached a canonical terminal outcome.
    Terminal {
        /// Exact terminal event sequence for every disposition.
        terminal_sequence: Sequence,
        /// Stable outcome class.
        disposition: ParallelBranchTerminalDisposition,
    },
}

