/// Hashes one exact runtime-owned plugin action proposal.
///
/// # Errors
///
/// Returns an error when deterministic JSON serialization fails.
pub fn plugin_node_runtime_action_proposal_hash(
    proposal: &PluginNodeRuntimeActionProposal,
) -> Result<ContentHash, SessionReducerError> {
    serde_json::to_vec(proposal)
        .map(|bytes| ContentHash::digest(&bytes))
        .map_err(|_| SessionReducerError::InvalidPluginNodeOutcomeApplication)
}

