/// Safe next action derived only from canonical artifact-persistence state.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ArtifactPersistenceResumeAction {
    /// Policy evaluation has no canonical outcome and must not be inferred.
    AwaitPolicyRecovery,
    /// The exact approved request may be dispatched for the first time.
    DispatchApproved,
    /// Dispatch may already have crossed the effect boundary; reconcile only.
    ReconcileReceipt,
    /// The effect is terminal and must not be dispatched again.
    CompleteNode,
}

/// Canonical artifact-persistence record reconstructed without opening storage.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct ArtifactPersistenceRecord {
    /// Exact graph/content/proposal identity.
    pub identity: ArtifactPersistenceIdentity,
    /// Requested and persisted media type.
    pub mime_type: String,
    /// Requested and persisted byte count.
    pub byte_size: u64,
    /// Latest durable outbox state.
    pub state: ArtifactPersistenceState,
    /// Digest of the approved action, once policy succeeds.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub action_digest: Option<ContentHash>,
    /// Canonical proposal sequence.
    pub proposed_at: Sequence,
    /// Canonical proposal event used as dependency creation provenance.
    pub proposed_event: EventId,
    /// Canonical approval sequence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub approved_at: Option<Sequence>,
    /// Canonical dispatch sequence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub dispatched_at: Option<Sequence>,
    /// Canonical terminal sequence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub completed_at: Option<Sequence>,
    /// Dependency-owned BLAKE3 content identity.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub artifact_id: Option<String>,
    /// Portable dependency-owned immutable reference.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub artifact_reference: Option<String>,
}

impl ArtifactPersistenceRecord {
    /// Returns the only restart action legal at this canonical cut.
    #[must_use]
    pub const fn resume_action(&self) -> ArtifactPersistenceResumeAction {
        match self.state {
            ArtifactPersistenceState::Proposed => {
                ArtifactPersistenceResumeAction::AwaitPolicyRecovery
            }
            ArtifactPersistenceState::Approved => ArtifactPersistenceResumeAction::DispatchApproved,
            ArtifactPersistenceState::Dispatched => {
                ArtifactPersistenceResumeAction::ReconcileReceipt
            }
            ArtifactPersistenceState::Completed => ArtifactPersistenceResumeAction::CompleteNode,
        }
    }
}

/// Replay-owned automatic memory-write outbox phase.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum AutomaticMemoryWriteState {
    /// Exact content and runtime timestamp are canonical.
    Proposed,
    /// Blocking policy approved the exact action.
    Approved,
    /// Dispatch intent was committed before provider access.
    Dispatched,
    /// The provider returned a terminal idempotent receipt.
    Completed,
    /// A definite terminal failure was committed.
    Failed,
    /// A non-idempotent plugin write may have crossed the effect boundary.
    Ambiguous,
}

/// Safe next action derived solely from canonical automatic-memory state.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum AutomaticMemoryWriteResumeAction {
    /// Policy began without a canonical outcome and must fail closed.
    AwaitPolicyRecovery,
    /// The approved exact request may be dispatched once.
    DispatchApproved,
    /// The idempotent exact request may be reconciled by replaying it.
    ReconcileIdempotentWrite,
    /// A non-idempotent plugin dispatch without a receipt must fail closed.
    AmbiguousFailClosed,
    /// The write is terminal and must not be dispatched again.
    Complete,
    /// The write failed definitively and is terminal.
    TerminallyFailed,
}

/// Canonical automatic-memory record reconstructed without querying a provider.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub struct AutomaticMemoryWriteRecord {
    /// Exact immutable write identity.
    pub identity: AutomaticMemoryWriteIdentity,
    /// Bounded typed content retained for exact recovery.
    pub content: String,
    /// Current canonical outbox phase.
    pub state: AutomaticMemoryWriteState,
    /// Approved exact action digest.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub action_digest: Option<ContentHash>,
    /// Proposal sequence.
    pub proposed_at: Sequence,
    /// Approval sequence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub approved_at: Option<Sequence>,
    /// Dispatch sequence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub dispatched_at: Option<Sequence>,
    /// Terminal sequence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub completed_at: Option<Sequence>,
    /// Provider-local immutable reference.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub reference: Option<String>,
    /// Whether the provider retained the record.
    #[serde(default)]
    pub retained: bool,
    /// Stable terminal failure or ambiguity code.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub failure_code: Option<String>,
    /// Hash of the exact value accepted by a plugin provider.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub value_hash: Option<ContentHash>,
    /// Sealed terminal plugin receipt evidence.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub terminal_receipt: Option<SealedPluginContextReceipt>,
}

impl AutomaticMemoryWriteRecord {
    /// Returns the only restart action legal at this canonical cut.
    #[must_use]
    pub const fn resume_action(&self) -> AutomaticMemoryWriteResumeAction {
        match self.state {
            AutomaticMemoryWriteState::Proposed => {
                AutomaticMemoryWriteResumeAction::AwaitPolicyRecovery
            }
            AutomaticMemoryWriteState::Approved => {
                AutomaticMemoryWriteResumeAction::DispatchApproved
            }
            AutomaticMemoryWriteState::Dispatched if self.identity.plugin.is_some() => {
                AutomaticMemoryWriteResumeAction::AmbiguousFailClosed
            }
            AutomaticMemoryWriteState::Dispatched => {
                AutomaticMemoryWriteResumeAction::ReconcileIdempotentWrite
            }
            AutomaticMemoryWriteState::Completed => AutomaticMemoryWriteResumeAction::Complete,
            AutomaticMemoryWriteState::Failed => AutomaticMemoryWriteResumeAction::TerminallyFailed,
            AutomaticMemoryWriteState::Ambiguous => {
                AutomaticMemoryWriteResumeAction::AmbiguousFailClosed
            }
        }
    }
}

