    #[test]
    fn immutable_binding_restart_preserves_exact_plugin_memory_and_compactor_selections() {
        let mut binding = binding(BuiltInStyle::PersistentChat);
        binding.memory.plugin = Some(SessionPluginMemoryConfiguration {
            plugin_id: String::from("fixture.context"),
            plugin_version: String::from("2.3.4"),
            provider_id: String::from("fixture.memory"),
            provider_version: String::from("1.4.0"),
            declaration_hash: ContentHash::digest(b"memory declaration"),
            configuration_reference: ContentHash::digest(b"memory configuration"),
        });
        binding.compaction.plugin = Some(SessionPluginCompactorConfiguration {
            plugin_id: String::from("fixture.context"),
            plugin_version: String::from("2.3.4"),
            compactor_id: String::from("fixture.compactor"),
            compactor_version: String::from("3.1.0"),
            declaration_hash: ContentHash::digest(b"compactor declaration"),
            configuration_reference: ContentHash::digest(b"compactor configuration"),
        });

        let encoded = serde_json::to_string(&binding).expect("binding serialization");
        let restarted: SessionStyleBinding =
            serde_json::from_str(&encoded).expect("binding restart");
        assert_eq!(restarted, binding);

        let mut legacy = serde_json::to_value(&binding).expect("legacy binding value");
        legacy["memory"]
            .as_object_mut()
            .expect("memory object")
            .remove("plugin");
        legacy["compaction"]
            .as_object_mut()
            .expect("compaction object")
            .remove("plugin");
        let migrated: SessionStyleBinding =
            serde_json::from_value(legacy).expect("legacy binding migration");
        assert!(migrated.memory.plugin.is_none());
        assert!(migrated.compaction.plugin.is_none());
    }

