    #[test]
    fn plugin_automatic_memory_terminal_receipts_are_exact_and_bounded() {
        let (dispatched, identity, action_digest) = dispatched_plugin_automatic_memory_write();
        assert!(matches!(
            reduce(
                Some(dispatched.clone()),
                &envelope(
                    6,
                    RuntimeCommittedEvent::AutomaticMemoryWriteFailed(Box::new(
                        AutomaticMemoryWriteFailedEvent {
                            identity: identity.clone(),
                            action_digest: Some(action_digest),
                            code: String::from("definite_worker_failure"),
                            terminal_receipt: None,
                        },
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidAutomaticMemoryWrite)
        ));
        let receipt = SealedPluginContextReceipt {
            receipt_hash: ContentHash::digest(b"write receipt"),
            receipt_reference: String::from("plugin-receipt:write:1"),
        };
        let failed = reduce(
            Some(dispatched.clone()),
            &envelope(
                6,
                RuntimeCommittedEvent::AutomaticMemoryWriteFailed(Box::new(
                    AutomaticMemoryWriteFailedEvent {
                        identity: identity.clone(),
                        action_digest: Some(action_digest),
                        code: String::from("definite_worker_failure"),
                        terminal_receipt: Some(receipt.clone()),
                    },
                )),
            ),
        )
        .expect("definite failure");
        assert_eq!(
            failed.automatic_memory_writes[&identity.write_id].resume_action(),
            AutomaticMemoryWriteResumeAction::TerminallyFailed
        );
        let completed = reduce(
            Some(dispatched),
            &envelope(
                6,
                RuntimeCommittedEvent::AutomaticMemoryWriteCompleted(Box::new(
                    AutomaticMemoryWriteCompletedEvent {
                        identity: identity.clone(),
                        action_digest,
                        reference: String::from("memory:item-1"),
                        retained: true,
                        value_hash: identity.plugin.as_ref().map(|plugin| plugin.value_hash),
                        terminal_receipt: Some(receipt),
                    },
                )),
            ),
        )
        .expect("completed plugin write");
        assert_eq!(
            completed.automatic_memory_writes[&identity.write_id].state,
            AutomaticMemoryWriteState::Completed
        );
    }

    fn iteration_completion_graph() -> ExecutableGraph {
        compile_graph(
            r#"
format_version = 1
entry = "repeat"
[budget]
max_steps = 10
max_tokens = 100
max_cost_micros = 100
max_duration_ms = 1000
[declarations]
capabilities = []
[[nodes]]
id = "repeat"
kind = "loop"
max_iterations = 3
[[nodes]]
id = "done"
kind = "complete_session"
[[edges]]
from = "repeat"
to = "done"
"#,
            &GraphCacheInputs {
                plugin_set_hash: ContentHash::digest(b"iteration-memory-plugins"),
                runtime_api_version: String::from("1.0.0"),
                capability_set: BTreeSet::new(),
            },
            CompilerLimits::default(),
        )
        .expect("iteration completion graph")
    }

    fn iteration_completion_state() -> (
        SessionState,
        SuccessfulIterationCompletionBoundary,
        EventEnvelope<RuntimeCommittedEvent>,
    ) {
        let transition = envelope(
            5,
            RuntimeCommittedEvent::StyleTransitionSelected(StyleTransitionSelectedEvent {
                from_node_id: String::from("repeat"),
                to_node_id: String::from("done"),
                attempt: 1,
                loop_iteration: 0,
                step: 1,
            }),
        );
        let events = vec![
            created(),
            envelope(
                2,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(iteration_completion_graph()),
                        input_reference: None,
                        execution_contract: None,
                    },
                )),
            ),
            envelope(
                3,
                RuntimeCommittedEvent::StyleNodeEntered(StyleNodeEnteredEvent {
                    node_id: String::from("repeat"),
                    attempt: 1,
                    loop_iteration: 0,
                    step: 1,
                }),
            ),
            envelope(
                4,
                RuntimeCommittedEvent::StyleNodeCompleted(StyleNodeCompletedEvent {
                    node_id: String::from("repeat"),
                    attempt: 1,
                    loop_iteration: 0,
                    step: 1,
                    result_reference: Some(String::from("iteration:remaining:false")),
                    artifact_reference: None,
                }),
            ),
            transition.clone(),
        ];
        let state = replay(&events).expect("iteration transition replay");
        let boundary = SuccessfulIterationCompletionBoundary {
            loop_node_id: String::from("repeat"),
            destination_node_id: String::from("done"),
            attempt: 1,
            loop_iteration: 0,
            step: 1,
            sequence: transition.metadata.sequence,
            event_checksum: transition.integrity_checksum,
        };
        (state, boundary, transition)
    }

    fn iteration_memory_identity(
        content: &str,
        boundary: &SuccessfulIterationCompletionBoundary,
    ) -> AutomaticMemoryWriteIdentity {
        let run_id = String::from("iteration-run-0");
        let mut identity = AutomaticMemoryWriteIdentity {
            write_id: String::new(),
            run_id: run_id.clone(),
            request_hash: ContentHash::digest(b"iteration request"),
            session_completion: None,
            iteration_completion: Some(boundary.clone()),
            policy: String::from("iteration_completion"),
            provider: String::from("file"),
            scope: format!("session:{}", session_id()),
            source: automatic_memory_iteration_source(&run_id, boundary).expect("iteration source"),
            content_hash: ContentHash::digest(content.as_bytes()),
            byte_size: u64::try_from(content.len()).expect("content size"),
            created_at_millis: 17,
            plugin: None,
        };
        identity.write_id =
            automatic_memory_write_id(session_id(), &identity).expect("iteration write ID");
        identity
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one boundary-substitution matrix proves every persisted iteration field and duplicate key"
    )]
    fn iteration_completion_memory_binds_exact_transition_and_rejects_duplicates() {
        let (mut state, boundary, _) = iteration_completion_state();
        assert_eq!(
            state.successful_iteration_completions,
            vec![boundary.clone()]
        );
        let mut style_binding = binding(BuiltInStyle::PersistentChat);
        style_binding.memory.provider = String::from("file");
        style_binding.memory.scopes = vec![String::from("session")];
        style_binding.memory.write_policy = String::from("iteration_completion");
        state.style_binding = Some(style_binding);
        let content = r#"{"schema":"agentmod.iteration-memory.v1","iteration":0}"#;
        let identity = iteration_memory_identity(content, &boundary);

        for substituted_boundary in [
            {
                let mut value = boundary.clone();
                value.loop_node_id = String::from("other-loop");
                value
            },
            {
                let mut value = boundary.clone();
                value.destination_node_id = String::from("substituted");
                value
            },
            {
                let mut value = boundary.clone();
                value.loop_iteration = 1;
                value
            },
            {
                let mut value = boundary.clone();
                value.sequence = value.sequence.checked_next().expect("next sequence");
                value
            },
            {
                let mut value = boundary.clone();
                value.event_checksum = ContentHash::digest(b"substituted transition");
                value
            },
        ] {
            let substituted = iteration_memory_identity(content, &substituted_boundary);
            assert!(matches!(
                reduce(
                    Some(state.clone()),
                    &envelope(
                        6,
                        RuntimeCommittedEvent::AutomaticMemoryWriteProposed(Box::new(
                            AutomaticMemoryWriteProposedEvent {
                                identity: substituted,
                                content: content.to_owned(),
                            },
                        )),
                    ),
                ),
                Err(SessionReducerError::InvalidAutomaticMemoryWrite)
            ));
        }

        let mut missing = identity.clone();
        missing.iteration_completion = None;
        missing.source =
            String::from("runtime.automatic_memory:iteration_completion:iteration-run-0");
        missing.write_id =
            automatic_memory_write_id(session_id(), &missing).expect("legacy-shaped write ID");
        assert!(matches!(
            reduce(
                Some(state.clone()),
                &envelope(
                    6,
                    RuntimeCommittedEvent::AutomaticMemoryWriteProposed(Box::new(
                        AutomaticMemoryWriteProposedEvent {
                            identity: missing,
                            content: content.to_owned(),
                        },
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidAutomaticMemoryWrite)
        ));

        let proposed = reduce(
            Some(state),
            &envelope(
                6,
                RuntimeCommittedEvent::AutomaticMemoryWriteProposed(Box::new(
                    AutomaticMemoryWriteProposedEvent {
                        identity: identity.clone(),
                        content: content.to_owned(),
                    },
                )),
            ),
        )
        .expect("exact iteration write");
        let duplicate_content =
            r#"{"schema":"agentmod.iteration-memory.v1","iteration":0,"duplicate":true}"#;
        let mut duplicate = iteration_memory_identity(duplicate_content, &boundary);
        duplicate.created_at_millis = 18;
        duplicate.write_id =
            automatic_memory_write_id(session_id(), &duplicate).expect("duplicate write ID");
        assert_ne!(duplicate.write_id, identity.write_id);
        assert!(matches!(
            reduce(
                Some(proposed),
                &envelope(
                    7,
                    RuntimeCommittedEvent::AutomaticMemoryWriteProposed(Box::new(
                        AutomaticMemoryWriteProposedEvent {
                            identity: duplicate,
                            content: duplicate_content.to_owned(),
                        },
                    )),
                ),
            ),
            Err(SessionReducerError::DuplicateAutomaticMemoryWrite)
        ));
    }

    #[test]
    fn iteration_completion_state_field_is_serde_defaulted_for_legacy_snapshots() {
        let (state, _, _) = iteration_completion_state();
        let mut encoded = serde_json::to_value(state).expect("state JSON");
        encoded
            .as_object_mut()
            .expect("state object")
            .remove("successful_iteration_completions");
        let legacy: SessionState = serde_json::from_value(encoded).expect("legacy state");
        assert!(legacy.successful_iteration_completions.is_empty());
    }

    #[test]
    fn plugin_activation_and_invocation_replay_into_inspectable_state() {
        let style_binding = binding(BuiltInStyle::PersistentChat);
        let plugin_set_hash = style_binding.plugin_set_hash;
        let events = vec![
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: style_binding.id.clone(),
                    style_binding: Some(Box::new(style_binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::PluginSetActivated(PluginSetActivatedEvent {
                    plugin_ids: vec![String::from("fixture.rewriter")],
                    plugin_set_hash,
                }),
            ),
            envelope(
                3,
                RuntimeCommittedEvent::PluginInvocationCompleted(PluginInvocationCompletedEvent {
                    plugin_id: String::from("fixture.rewriter"),
                    handler: String::from("rewrite-tool"),
                    action_kind: String::from("tool_call"),
                    proposal_id: String::from("tool-call:fixture"),
                    input_digest: ContentHash::digest(b"input"),
                    output_digest: Some(ContentHash::digest(b"output")),
                    outcome: String::from("replace"),
                }),
            ),
        ];
        let state = replay(&events).expect("plugin replay");
        assert_eq!(
            state.plugins.activated_plugin_ids,
            vec![String::from("fixture.rewriter")]
        );
        assert_eq!(
            state.plugins.activated_at,
            Some(Sequence::new(2).expect("sequence"))
        );
        assert_eq!(state.plugins.invocations.len(), 1);
        assert_eq!(state.plugins.invocations[0].outcome, "replace");
        assert_eq!(
            state.plugins.invocations[0].input_digest,
            Some(ContentHash::digest(b"input"))
        );
        assert_eq!(
            state.plugins.invocations[0].output_digest,
            Some(ContentHash::digest(b"output"))
        );
    }

    #[test]
    fn rejected_and_failed_plugin_invocations_are_canonical_and_same_session_can_continue() {
        let style_binding = binding(BuiltInStyle::PersistentChat);
        let plugin_set_hash = style_binding.plugin_set_hash;
        let prefix = vec![
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: style_binding.id.clone(),
                    style_binding: Some(Box::new(style_binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::PluginSetActivated(PluginSetActivatedEvent {
                    plugin_ids: vec![String::from("fixture.guard")],
                    plugin_set_hash,
                }),
            ),
            envelope(
                3,
                RuntimeCommittedEvent::PluginInvocationCompleted(PluginInvocationCompletedEvent {
                    plugin_id: String::from("fixture.guard"),
                    handler: String::from("reject-tool"),
                    action_kind: String::from("tool_call"),
                    proposal_id: String::from("tool-call:rejected"),
                    input_digest: ContentHash::digest(b"rejected input"),
                    output_digest: None,
                    outcome: String::from("reject"),
                }),
            ),
            envelope(
                4,
                RuntimeCommittedEvent::PluginInvocationCompleted(PluginInvocationCompletedEvent {
                    plugin_id: String::from("fixture.guard"),
                    handler: String::from("failure-tool"),
                    action_kind: String::from("tool_call"),
                    proposal_id: String::from("tool-call:failed"),
                    input_digest: ContentHash::digest(b"failed input"),
                    output_digest: None,
                    outcome: String::from("failure"),
                }),
            ),
        ];
        let recovered = replay(&prefix).expect("rejected/failed audit replay");
        assert_eq!(
            recovered
                .plugins
                .invocations
                .iter()
                .map(|record| record.outcome.as_str())
                .collect::<Vec<_>>(),
            ["reject", "failure"]
        );
        let continued = reduce(
            Some(recovered),
            &envelope(
                5,
                RuntimeCommittedEvent::PluginInvocationCompleted(PluginInvocationCompletedEvent {
                    plugin_id: String::from("fixture.guard"),
                    handler: String::from("continue-tool"),
                    action_kind: String::from("tool_call"),
                    proposal_id: String::from("tool-call:continued"),
                    input_digest: ContentHash::digest(b"continued input"),
                    output_digest: Some(ContentHash::digest(b"continued output")),
                    outcome: String::from("continue"),
                }),
            ),
        )
        .expect("same session accepts a later exact invocation");
        assert_eq!(continued.plugins.invocations.len(), 3);
        assert_eq!(
            continued.plugins.invocations[2].input_digest,
            Some(ContentHash::digest(b"continued input"))
        );
        assert_eq!(
            continued.plugins.invocations[2].output_digest,
            Some(ContentHash::digest(b"continued output"))
        );
        assert_eq!(continued.plugins.invocations[2].outcome, "continue");
    }

    #[test]
    fn plugin_invocation_audit_rejects_unknown_or_digest_inconsistent_outcomes() {
        let style_binding = binding(BuiltInStyle::PersistentChat);
        let plugin_set_hash = style_binding.plugin_set_hash;
        let activated = replay(&[
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: style_binding.id.clone(),
                    style_binding: Some(Box::new(style_binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::PluginSetActivated(PluginSetActivatedEvent {
                    plugin_ids: vec![String::from("fixture.guard")],
                    plugin_set_hash,
                }),
            ),
        ])
        .expect("activated plugin");
        for (outcome, output_digest) in [
            ("continue", None),
            ("replace", None),
            ("reject", Some(ContentHash::digest(b"forged output"))),
            ("failure", Some(ContentHash::digest(b"forged output"))),
            ("unknown", None),
        ] {
            assert!(matches!(
                reduce(
                    Some(activated.clone()),
                    &envelope(
                        3,
                        RuntimeCommittedEvent::PluginInvocationCompleted(
                            PluginInvocationCompletedEvent {
                                plugin_id: String::from("fixture.guard"),
                                handler: String::from("guard-tool"),
                                action_kind: String::from("tool_call"),
                                proposal_id: String::from("tool-call:fixture"),
                                input_digest: ContentHash::digest(b"input"),
                                output_digest,
                                outcome: outcome.to_owned(),
                            },
                        ),
                    ),
                ),
                Err(SessionReducerError::InvalidPluginInvocation)
            ));
        }
    }

