    fn plugin_node_outcome_proposal() -> CanonicalPluginNodeOutcomeProposal {
        let output = serde_json::json!({"answer": 42});
        let preserved_state = serde_json::json!({"cursor": "next"});
        let action_payload = serde_json::json!({"event_type": "fixture.ready"});
        let proposed_actions = vec![CanonicalPluginNodeActionProposal {
            kind: String::from("emit_event"),
            action_hash: plugin_node_action_hash("emit_event", &action_payload)
                .expect("action hash"),
            payload: action_payload,
        }];
        CanonicalPluginNodeOutcomeProposal {
            output_hash: plugin_node_value_hash(&output).expect("output hash"),
            output,
            preserved_state_hash: plugin_node_value_hash(&preserved_state)
                .expect("preserved-state hash"),
            preserved_state,
            proposed_actions_hash: plugin_node_actions_hash(&proposed_actions)
                .expect("actions hash"),
            proposed_actions,
        }
    }

