    fn plugin_node_application<'a>(
        state: &'a SessionState,
        identity: &PluginNodeInvocationIdentity,
    ) -> &'a PluginNodeOutcomeApplicationRecord {
        state
            .style_execution
            .as_ref()
            .expect("execution")
            .plugin_node_invocations
            .get(&identity.invocation_id)
            .expect("invocation")
            .outcome_application
            .as_deref()
            .expect("outcome application")
    }

    #[test]
    fn plugin_node_outcome_application_reconstructs_every_restart_prefix() {
        let (identity, proposal, mut events) = completed_plugin_node_events();
        let application_events = plugin_node_application_events(&identity, &proposal);
        for (offset, payload) in application_events.iter().cloned().enumerate() {
            events.push(envelope(
                u64::try_from(offset).expect("offset") + 8,
                payload,
            ));
            let state = replay(&events)
                .unwrap_or_else(|error| panic!("restart prefix {offset}: {error:?}"));
            let application = plugin_node_application(&state, &identity);
            assert_eq!(application.validated.action_hashes.len(), 1);
            match offset {
                0 => {
                    assert!(application.budget_charge.is_none());
                    assert!(application.actions.is_empty());
                    assert!(application.preserved_state.is_none());
                }
                1 => {
                    assert!(application.budget_charge.is_none());
                    assert!(application.actions[0].terminal.is_none());
                }
                2 => {
                    assert!(application.budget_charge.is_none());
                    assert!(matches!(
                        application.actions[0].terminal,
                        Some(PluginNodeActionTerminalRecord::Applied(_))
                    ));
                }
                3 => {
                    assert!(application.budget_charge.is_some());
                    assert!(application.preserved_state.is_none());
                }
                4 => assert!(application.preserved_state.is_some()),
                _ => unreachable!("bounded application prefix"),
            }
            let encoded = serde_json::to_vec(&state).expect("serialize prefix");
            let restarted: SessionState =
                serde_json::from_slice(&encoded).expect("deserialize prefix");
            assert_eq!(state, restarted);
        }

        let state = replay(&events).expect("complete application");
        let mut legacy = serde_json::to_value(
            state
                .style_execution
                .as_ref()
                .expect("execution")
                .plugin_node_invocations
                .get(&identity.invocation_id)
                .expect("invocation"),
        )
        .expect("record json");
        legacy
            .as_object_mut()
            .expect("record object")
            .remove("outcome_application");
        let legacy: PluginNodeInvocationRecord =
            serde_json::from_value(legacy).expect("legacy record");
        assert!(legacy.outcome_application.is_none());
    }

    #[test]
    fn plugin_node_outcome_rejection_is_canonical_terminal_replay_authority() {
        let (identity, _proposal, mut events) = completed_plugin_node_events();
        let completed_state = replay(&events).expect("completed proposal");
        let rejected = prepare_plugin_node_outcome_rejection(
            &completed_state,
            &identity.invocation_id,
            "invalid_schema",
        )
        .expect("rejection event");
        assert_eq!(
            classify_plugin_node_outcome_rejection(&completed_state, &rejected),
            PluginNodeOutcomeRejectionDisposition::Append
        );
        assert_eq!(
            classify_plugin_node_invocation_recovery(&completed_state, &identity.invocation_id),
            PluginNodeInvocationRecovery::CompleteFromCanonicalProposal
        );

        events.push(envelope(
            8,
            RuntimeCommittedEvent::PluginNodeOutcomeRejected(Box::new(rejected.clone())),
        ));
        let rejected_state = replay(&events).expect("canonical rejection");
        let record = rejected_state
            .style_execution
            .as_ref()
            .expect("execution")
            .plugin_node_invocations
            .get(&identity.invocation_id)
            .expect("invocation");
        assert_eq!(record.state, PluginNodeInvocationState::Completed);
        assert_eq!(record.failure_code.as_deref(), Some("invalid_schema"));
        assert!(record.outcome_application.is_none());
        assert_eq!(
            classify_plugin_node_outcome_rejection(&rejected_state, &rejected),
            PluginNodeOutcomeRejectionDisposition::AlreadyCommitted
        );
        assert_eq!(
            classify_plugin_node_invocation_recovery(&rejected_state, &identity.invocation_id),
            PluginNodeInvocationRecovery::TerminallyFailed
        );

        let encoded = serde_json::to_vec(&rejected_state).expect("serialize rejected state");
        let restarted: SessionState =
            serde_json::from_slice(&encoded).expect("deserialize rejected state");
        assert_eq!(rejected_state, restarted);
        assert_eq!(
            classify_plugin_node_invocation_recovery(&restarted, &identity.invocation_id),
            PluginNodeInvocationRecovery::TerminallyFailed
        );
        assert_eq!(replay(&events).expect("pure replay"), rejected_state);
    }

    #[test]
    fn plugin_node_outcome_rejection_replays_every_crash_prefix_without_redispatch() {
        let (identity, _proposal, events) = completed_plugin_node_events();
        let expected = [
            PluginNodeInvocationRecovery::NotStarted,
            PluginNodeInvocationRecovery::NotStarted,
            PluginNodeInvocationRecovery::NotStarted,
            PluginNodeInvocationRecovery::AwaitingAuthorization,
            PluginNodeInvocationRecovery::SafeToDispatchOnce,
            PluginNodeInvocationRecovery::WaitingForTerminalReceipt,
            PluginNodeInvocationRecovery::CompleteFromCanonicalProposal,
        ];
        for prefix_len in 1..=events.len() {
            let state = replay(&events[..prefix_len])
                .unwrap_or_else(|error| panic!("crash prefix {prefix_len}: {error:?}"));
            assert_eq!(
                classify_plugin_node_invocation_recovery(&state, &identity.invocation_id),
                expected[prefix_len - 1],
                "crash prefix {prefix_len}"
            );
        }

        let completed_state = replay(&events).expect("completed state");
        let rejected = prepare_plugin_node_outcome_rejection(
            &completed_state,
            &identity.invocation_id,
            "invalid_transition",
        )
        .expect("rejection");
        let mut rejected_events = events;
        rejected_events.push(envelope(
            8,
            RuntimeCommittedEvent::PluginNodeOutcomeRejected(Box::new(rejected)),
        ));
        let state = replay(&rejected_events).expect("rejected prefix");
        assert_eq!(
            classify_plugin_node_invocation_recovery(&state, &identity.invocation_id),
            PluginNodeInvocationRecovery::TerminallyFailed
        );
        assert_eq!(replay(&rejected_events).expect("restart replay"), state);
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the exact rejection binding substitution matrix is intentionally explicit"
    )]
    fn plugin_node_outcome_rejection_rejects_duplicates_and_every_binding_substitution() {
        let (identity, _proposal, events) = completed_plugin_node_events();
        let completed_state = replay(&events).expect("completed proposal");
        let rejected = prepare_plugin_node_outcome_rejection(
            &completed_state,
            &identity.invocation_id,
            "invalid_schema",
        )
        .expect("rejection");
        let mut canonical_events = events.clone();
        canonical_events.push(envelope(
            8,
            RuntimeCommittedEvent::PluginNodeOutcomeRejected(Box::new(rejected.clone())),
        ));
        let rejected_state = replay(&canonical_events).expect("canonical rejection");

        let mut duplicate = canonical_events.clone();
        duplicate.push(envelope(
            9,
            RuntimeCommittedEvent::PluginNodeOutcomeRejected(Box::new(rejected.clone())),
        ));
        assert!(matches!(
            replay(&duplicate),
            Err(SessionReducerError::InvalidPluginNodeOutcomeApplication)
        ));

        let mut substitutions = Vec::new();

        let mut changed = rejected.clone();
        changed.identity.input_hash = ContentHash::digest(b"substituted-input");
        substitutions.push(changed);

        let mut changed = rejected.clone();
        changed.proposal_hash = ContentHash::digest(b"substituted-proposal");
        substitutions.push(changed);

        let mut changed = rejected.clone();
        changed.prior_completed_event_id = EventId::from_uuid(Uuid::from_u128(999));
        substitutions.push(changed);

        let mut changed = rejected.clone();
        changed.version = PLUGIN_NODE_OUTCOME_REJECTION_VERSION + 1;
        substitutions.push(changed);

        let mut changed = rejected.clone();
        changed.diagnostic_hash = ContentHash::digest(b"substituted-diagnostic");
        substitutions.push(changed);

        let mut changed = rejected.clone();
        changed.code = String::from("invalid_transition");
        changed.diagnostic_hash =
            plugin_node_outcome_rejection_diagnostic_hash(&changed.code).expect("diagnostic hash");
        substitutions.push(changed);

        for (index, substitution) in substitutions.into_iter().enumerate() {
            assert_eq!(
                classify_plugin_node_outcome_rejection(&rejected_state, &substitution),
                PluginNodeOutcomeRejectionDisposition::Conflict,
                "substitution {index}"
            );
            let mut substituted_events = canonical_events.clone();
            substituted_events.push(envelope(
                9,
                RuntimeCommittedEvent::PluginNodeOutcomeRejected(Box::new(substitution)),
            ));
            assert!(
                matches!(
                    replay(&substituted_events),
                    Err(SessionReducerError::InvalidPluginNodeOutcomeApplication)
                ),
                "substitution {index}"
            );
        }
    }

