    #[test]
    fn plugin_node_invocation_replays_exact_outbox_and_retains_proposal_only() {
        let (identity, mut events) = plugin_node_invocation_fixture();
        events.push(envelope(
            4,
            RuntimeCommittedEvent::PluginNodeInvocationProposed(Box::new(
                PluginNodeInvocationProposedEvent {
                    identity: identity.clone(),
                },
            )),
        ));
        append_plugin_node_authorized_and_dispatched(&identity, &mut events);
        let proposal = plugin_node_outcome_proposal();
        events.push(envelope(
            7,
            RuntimeCommittedEvent::PluginNodeInvocationCompleted(Box::new(
                PluginNodeInvocationCompletedEvent {
                    identity: identity.clone(),
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(106)),
                    proposal: proposal.clone(),
                    attempts: 1,
                },
            )),
        ));

        let state = replay(&events).expect("plugin-node replay");
        let execution = state.style_execution.as_ref().expect("execution");
        let record = execution
            .plugin_node_invocations
            .get(&identity.invocation_id)
            .expect("invocation");
        assert_eq!(record.identity, identity);
        assert_eq!(record.state, PluginNodeInvocationState::Completed);
        assert_eq!(record.proposal.as_deref(), Some(&proposal));
        assert_eq!(
            classify_plugin_node_invocation_recovery(&state, &identity.invocation_id),
            PluginNodeInvocationRecovery::CompleteFromCanonicalProposal
        );
        assert!(execution.completed_nodes.is_empty());
        assert!(execution.emitted_user_events.is_empty());
        assert!(
            execution
                .canonical_variables
                .as_ref()
                .expect("variables")
                .environment()
                .canonical_entries()
                .is_empty()
        );

        let replayed_again = replay(&events).expect("pure second replay");
        assert_eq!(state, replayed_again);
        let encoded = serde_json::to_vec(execution).expect("projection serialization");
        let decoded: StyleExecutionState =
            serde_json::from_slice(&encoded).expect("projection deserialization");
        assert_eq!(execution, &decoded);

        let mut legacy = serde_json::to_value(execution).expect("legacy projection");
        legacy
            .as_object_mut()
            .expect("projection object")
            .remove("plugin_node_invocations");
        let legacy: StyleExecutionState =
            serde_json::from_value(legacy).expect("serde-defaulted legacy projection");
        assert!(legacy.plugin_node_invocations.is_empty());
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the restart matrix intentionally retains every canonical lifecycle cut"
    )]
    fn plugin_node_recovery_classifies_every_restart_cut_and_ambiguity_fails_closed() {
        let (identity, mut events) = plugin_node_invocation_fixture();
        assert_eq!(
            classify_plugin_node_invocation_recovery(
                &replay(&events).expect("before proposal"),
                &identity.invocation_id
            ),
            PluginNodeInvocationRecovery::NotStarted
        );
        events.push(envelope(
            4,
            RuntimeCommittedEvent::PluginNodeInvocationProposed(Box::new(
                PluginNodeInvocationProposedEvent {
                    identity: identity.clone(),
                },
            )),
        ));
        assert_eq!(
            classify_plugin_node_invocation_recovery(
                &replay(&events).expect("proposed"),
                &identity.invocation_id
            ),
            PluginNodeInvocationRecovery::AwaitingAuthorization
        );
        events.push(envelope(
            5,
            RuntimeCommittedEvent::PluginNodeInvocationAuthorized(Box::new(
                PluginNodeInvocationAuthorizedEvent {
                    identity: identity.clone(),
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(104)),
                    authorization_digest: ContentHash::digest(b"keyed authorization"),
                },
            )),
        ));
        assert_eq!(
            classify_plugin_node_invocation_recovery(
                &replay(&events).expect("authorized"),
                &identity.invocation_id
            ),
            PluginNodeInvocationRecovery::SafeToDispatchOnce
        );
        events.push(envelope(
            6,
            RuntimeCommittedEvent::PluginNodeInvocationDispatched(Box::new(
                PluginNodeInvocationDispatchedEvent {
                    identity: identity.clone(),
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(105)),
                    authorization_digest: ContentHash::digest(b"keyed authorization"),
                    dispatch_digest: ContentHash::digest(b"bounded plugin-host frame"),
                },
            )),
        ));
        assert_eq!(
            classify_plugin_node_invocation_recovery(
                &replay(&events).expect("dispatched"),
                &identity.invocation_id
            ),
            PluginNodeInvocationRecovery::WaitingForTerminalReceipt
        );
        let mut failed_events = events.clone();
        failed_events.push(envelope(
            7,
            RuntimeCommittedEvent::PluginNodeInvocationFailed(Box::new(
                PluginNodeInvocationFailedEvent {
                    identity: identity.clone(),
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(106)),
                    code: String::from("worker_rejected"),
                    diagnostic: Some(String::from("definite no-effect receipt")),
                    attempts: 1,
                },
            )),
        ));
        assert_eq!(
            classify_plugin_node_invocation_recovery(
                &replay(&failed_events).expect("definite failure"),
                &identity.invocation_id
            ),
            PluginNodeInvocationRecovery::TerminallyFailed
        );
        events.push(envelope(
            7,
            RuntimeCommittedEvent::PluginNodeInvocationAmbiguous(Box::new(
                PluginNodeInvocationAmbiguousEvent {
                    identity: identity.clone(),
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(106)),
                    code: String::from("terminal_receipt_missing"),
                    diagnostic: Some(String::from("worker exited after dispatch")),
                    attempts: 1,
                },
            )),
        ));
        let ambiguous = replay(&events).expect("ambiguous terminal");
        assert_eq!(
            classify_plugin_node_invocation_recovery(&ambiguous, &identity.invocation_id),
            PluginNodeInvocationRecovery::AmbiguousFailClosed
        );

        events.push(envelope(
            8,
            RuntimeCommittedEvent::PluginNodeInvocationCompleted(Box::new(
                PluginNodeInvocationCompletedEvent {
                    identity,
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(107)),
                    proposal: plugin_node_outcome_proposal(),
                    attempts: 1,
                },
            )),
        ));
        assert!(matches!(
            replay(&events),
            Err(SessionReducerError::InvalidPluginNodeInvocation)
        ));
    }

    #[test]
    fn plugin_node_replay_rejects_tampered_identity_hashes_and_unbounded_results() {
        let (identity, base) = plugin_node_invocation_fixture();

        let mut wrong_identity = identity.clone();
        wrong_identity.executor.executor_declaration_hash =
            ContentHash::digest(b"substituted declaration");
        let mut events = base.clone();
        events.push(envelope(
            4,
            RuntimeCommittedEvent::PluginNodeInvocationProposed(Box::new(
                PluginNodeInvocationProposedEvent {
                    identity: wrong_identity,
                },
            )),
        ));
        assert!(matches!(
            replay(&events),
            Err(SessionReducerError::InvalidPluginNodeInvocation)
        ));

        let mut events = base.clone();
        events.push(envelope(
            4,
            RuntimeCommittedEvent::PluginNodeInvocationProposed(Box::new(
                PluginNodeInvocationProposedEvent {
                    identity: identity.clone(),
                },
            )),
        ));
        append_plugin_node_authorized_and_dispatched(&identity, &mut events);
        let mut tampered = plugin_node_outcome_proposal();
        tampered.output = serde_json::json!({"answer": 43});
        events.push(envelope(
            7,
            RuntimeCommittedEvent::PluginNodeInvocationCompleted(Box::new(
                PluginNodeInvocationCompletedEvent {
                    identity: identity.clone(),
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(106)),
                    proposal: tampered,
                    attempts: 1,
                },
            )),
        ));
        assert!(matches!(
            replay(&events),
            Err(SessionReducerError::InvalidPluginNodeInvocation)
        ));

        let action = plugin_node_outcome_proposal().proposed_actions[0].clone();
        assert!(matches!(
            plugin_node_actions_hash(&vec![action; MAX_PLUGIN_NODE_PROPOSED_ACTIONS + 1]),
            Err(SessionReducerError::InvalidPluginNodeInvocation)
        ));

        let mut events = base;
        events.push(envelope(
            4,
            RuntimeCommittedEvent::PluginNodeInvocationProposed(Box::new(
                PluginNodeInvocationProposedEvent {
                    identity: identity.clone(),
                },
            )),
        ));
        append_plugin_node_authorized_and_dispatched(&identity, &mut events);
        let oversized_output =
            serde_json::Value::String("x".repeat(MAX_PLUGIN_NODE_PROPOSAL_BYTES + 1));
        events.push(envelope(
            7,
            RuntimeCommittedEvent::PluginNodeInvocationCompleted(Box::new(
                PluginNodeInvocationCompletedEvent {
                    identity,
                    prior_event_id: EventId::from_uuid(Uuid::from_u128(106)),
                    proposal: CanonicalPluginNodeOutcomeProposal {
                        output_hash: ContentHash::digest(b"irrelevant"),
                        output: oversized_output,
                        preserved_state: serde_json::Value::Null,
                        preserved_state_hash: plugin_node_value_hash(&serde_json::Value::Null)
                            .expect("null hash"),
                        proposed_actions: vec![],
                        proposed_actions_hash: plugin_node_actions_hash(&[])
                            .expect("empty action hash"),
                    },
                    attempts: 1,
                },
            )),
        ));
        assert!(matches!(
            replay(&events),
            Err(SessionReducerError::InvalidPluginNodeInvocation)
        ));
    }

