    fn generic_child_executor_resolution(
        node: &agentmod_graph_engine::ExecutableNode,
    ) -> SessionNodeExecutorResolution {
        let executor_id = match node.kind {
            NodeKind::SpawnChildAgent => "runtime.child-spawn",
            NodeKind::WaitForAgents => "runtime.child-wait",
            NodeKind::Review => "runtime.review",
            NodeKind::Loop => "runtime.loop",
            NodeKind::CompleteSession => "runtime.session-completion",
            NodeKind::Fail => "runtime.fail",
            _ => panic!("unexpected generic-child fixture node"),
        };
        SessionNodeExecutorResolution {
            node_id: node.id.clone(),
            node_kind: serde_json::to_value(node.kind)
                .expect("node kind")
                .as_str()
                .expect("serialized node kind")
                .to_owned(),
            executor_id: executor_id.to_owned(),
            executor_version: String::from("1.0.0"),
            source: SessionNodeExecutorSource::Runtime,
            boundary: SessionNodeExecutorBoundary::RuntimeLogic,
            required_capabilities: node.required_capabilities.iter().cloned().collect(),
            resolved_capabilities: vec![String::from("agents"), String::from("model")],
            runtime_api_requirement: String::from("^1.0.0"),
            executor_declaration_hash: ContentHash::digest(executor_id.as_bytes()),
            adapter_configuration_reference: ContentHash::digest(
                &serde_json::to_vec(node).expect("compiled node"),
            ),
        }
    }

    fn generic_child_binding(graph: &ExecutableGraph) -> SessionStyleBinding {
        let mut result = binding(BuiltInStyle::PersistentChat);
        let mut compiled: CompiledSessionStyle =
            serde_json::from_str(&result.compiled_style_json).expect("compiled fixture");
        compiled.graph = graph.clone();
        result.compiled_style_json = serde_json::to_string(&compiled).expect("compiled graph");
        result.compiled_style_hash = ContentHash::digest(result.compiled_style_json.as_bytes());
        let mut plan = result.execution_plan.take().expect("base plan");
        plan.nodes = graph
            .nodes
            .iter()
            .map(generic_child_executor_resolution)
            .collect();
        plan.compilation.compiled_style_hash = result.compiled_style_hash;
        result.execution_plan_hash = Some(ContentHash::digest(
            &serde_json::to_vec(&plan).expect("execution plan"),
        ));
        result.execution_plan = Some(plan);
        result
    }

    fn generic_spawn_proposal(work: &NodeWorkIdentity, task_id: &str) -> ChildSpawnProposal {
        let task = serde_json::json!({"instruction": format!("complete {task_id}")});
        let mut proposal = ChildSpawnProposal {
            parent_session_id: session_id(),
            work: work.clone(),
            task_id: task_id.to_owned(),
            task_hash: ContentHash::digest(&serde_json::to_vec(&task).expect("task")),
            task,
            child_style: String::from("worker@1.0.0"),
            inherited_provider: None,
            inherited_model: None,
            inherited_mcp: None,
            tool_groups: BTreeSet::from([String::from("filesystem.read")]),
            depth: 1,
            token_budget: 1000,
            context_budget_tokens: 500,
            cost_budget_micros: 10_000,
            workspace: ResolvedChildWorkspace::SharedReadOnly,
            artifact_references: BTreeSet::from([String::from("artifact-brief")]),
            security_classification: SecurityClassification::Internal,
            approval_required: true,
            proposal_hash: ContentHash::from_bytes([0; 32]),
        };
        proposal.proposal_hash =
            ContentHash::digest(&serde_json::to_vec(&proposal).expect("zeroed proposal"));
        proposal
    }

    #[test]
    fn generic_child_action_digest_preserves_v1_v2_and_uses_v3_for_mcp() {
        let work = NodeWorkIdentity {
            run_id: String::from("run"),
            node_id: String::from("commission"),
            branch_path: Vec::new(),
            attempt: 1,
            loop_iteration: 0,
            step: 1,
        };
        let proposal = generic_spawn_proposal(&work, "task-a");
        let identity = GenericChildExecutionIdentity {
            execution_id: format!("generic-child:{}", proposal.proposal_hash),
            work,
            execution_plan_hash: ContentHash::digest(b"plan"),
            configuration_hash: ContentHash::digest(b"configuration"),
            proposal_hash: proposal.proposal_hash,
            task_id: proposal.task_id.clone(),
        };
        let mut contract = GenericChildSpawnContract {
            parent_session_id: proposal.parent_session_id,
            task: proposal.task,
            task_hash: proposal.task_hash,
            inherited_provider: None,
            inherited_model: None,
            inherited_mcp: None,
            tool_groups: proposal.tool_groups,
            depth: proposal.depth,
            context_budget_tokens: proposal.context_budget_tokens,
            cost_budget_micros: proposal.cost_budget_micros,
            workspace: serde_json::to_value(proposal.workspace).expect("workspace"),
            artifact_references: proposal.artifact_references,
            security_classification: String::from("internal"),
            approval_required: true,
            proposal_zero_json: String::from("{}"),
        };
        let v1 = generic_child_action_digest(&identity, &contract, "worker@1.0.0", 1_000)
            .expect("v1 digest");
        let expected_v1 = ContentHash::digest(
            &serde_json::to_vec(&(
                "agentmod.generic-child-action.v1",
                &identity,
                &contract,
                "worker@1.0.0",
                1_000_u64,
            ))
            .expect("v1 serialization"),
        );
        assert_eq!(v1, expected_v1);
        assert!(
            !serde_json::to_value(&contract)
                .expect("contract")
                .as_object()
                .expect("object")
                .contains_key("inherited_mcp")
        );

        contract.inherited_provider = Some(String::from("mock"));
        let v2 = generic_child_action_digest(&identity, &contract, "worker@1.0.0", 1_000)
            .expect("v2 digest");
        assert_ne!(v1, v2);

        contract.inherited_mcp = Some(SessionMcpBinding {
            schema_version: 1,
            declaration_hash: ContentHash::digest(b"mcp"),
            configuration_reference: Some(String::from("mcp-bootstrap.enc.json")),
            servers: vec![SessionMcpServerBinding {
                id: String::from("fixture"),
                display_name: String::from("Fixture"),
                transport: SessionMcpTransportBinding::StreamableHttp {
                    url: String::from("https://localhost.invalid/mcp"),
                    legacy_sse: false,
                    headers: Vec::new(),
                },
            }],
        });
        let v3 = generic_child_action_digest(&identity, &contract, "worker@1.0.0", 1_000)
            .expect("v3 digest");
        let expected_v3 = ContentHash::digest(
            &serde_json::to_vec(&(
                "agentmod.generic-child-action.v3",
                &identity,
                &contract,
                "worker@1.0.0",
                1_000_u64,
            ))
            .expect("v3 serialization"),
        );
        assert_eq!(v3, expected_v3);
        assert_ne!(v2, v3);
    }

    fn append_application_until_waiting(
        events: &mut Vec<EventEnvelope<RuntimeCommittedEvent>>,
        command: &PlanChildGraphApplicationCommand,
    ) {
        for _ in 0..32 {
            let state = replay(events.iter()).expect("prefix replay");
            assert_eq!(
                state,
                replay(events.iter()).expect("restart reconstructs identical state")
            );
            let plan = plan_child_graph_application(&state, command).expect("application planning");
            let Some(next) = plan.events.first().cloned() else {
                return;
            };
            let sequence = events.last().expect("event").metadata.sequence.get() + 1;
            events.push(envelope(sequence, next));
        }
        panic!("generic child application did not quiesce");
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the canonical child fixture keeps its graph, execution contract, and replay events visibly co-located"
    )]
    fn active_generic_children_fixture() -> (
        Vec<EventEnvelope<RuntimeCommittedEvent>>,
        PlanChildGraphApplicationCommand,
    ) {
        let graph = generic_child_graph();
        let style_binding = generic_child_binding(&graph);
        let contract = test_execution_contract(&style_binding, &graph);
        let resolution = contract
            .node_executors
            .iter()
            .find(|resolution| resolution.node_id == "commission")
            .expect("spawn executor");
        let work = NodeWorkIdentity {
            run_id: contract.run_id.clone(),
            node_id: String::from("commission"),
            branch_path: Vec::new(),
            attempt: 1,
            loop_iteration: 0,
            step: 1,
        };
        let proposals = vec![
            generic_spawn_proposal(&work, "task-b"),
            generic_spawn_proposal(&work, "task-a"),
        ];
        let mut events = vec![
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: style_binding.id.clone(),
                    style_binding: Some(Box::new(style_binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(graph),
                        input_reference: None,
                        execution_contract: Some(Box::new(contract.clone())),
                    },
                )),
            ),
            envelope(
                3,
                RuntimeCommittedEvent::StyleNodeEntered(StyleNodeEnteredEvent {
                    node_id: String::from("commission"),
                    attempt: 1,
                    loop_iteration: 0,
                    step: 1,
                }),
            ),
        ];
        let mut command = PlanChildGraphApplicationCommand {
            session_id: session_id(),
            work,
            execution_plan_hash: contract.execution_plan_hash,
            configuration_hash: resolution.adapter_configuration_reference,
            outcome: ChildGraphNodeOutcome::Spawn { proposals },
            evidence: ChildGraphApplicationEvidence::default(),
        };
        append_application_until_waiting(&mut events, &command);
        let proposed = replay(events.iter()).expect("proposed state");
        for record in proposed.child_agents.values() {
            command.evidence.approvals.insert(
                record.identity.task_id.clone(),
                record.action_digest.unwrap_or_else(|| {
                    generic_child_action_digest(
                        record
                            .generic_identity
                            .as_deref()
                            .expect("generic identity"),
                        record.generic.as_deref().expect("generic proposal"),
                        &record.child_style,
                        record.token_budget,
                    )
                    .expect("action digest")
                }),
            );
        }
        append_application_until_waiting(&mut events, &command);
        let dispatched = replay(events.iter()).expect("dispatched state");
        for (offset, record) in dispatched.child_agents.values().enumerate() {
            let child_session_id = SessionId::from_uuid(Uuid::from_u128(2_001 + offset as u128));
            command.evidence.creations.insert(
                record.identity.task_id.clone(),
                ChildCreationEvidence {
                    child_session_id,
                    parent_action_sequence: record.proposed_at,
                    child_link_hash: generic_child_link_hash(
                        record
                            .generic_identity
                            .as_deref()
                            .expect("generic identity"),
                        child_session_id,
                        record.proposed_at,
                        &record.child_style,
                    )
                    .expect("child link"),
                    workspace_lease: crate::workspace::test_workspace_lease(
                        crate::workspace::WorkspaceLeaseOwner {
                            parent_session_id: session_id(),
                            parent_action_sequence: record.proposed_at,
                            parent_graph_node_id: record.identity.node_id.clone(),
                            task_id: record.identity.task_id.clone(),
                        },
                        std::path::PathBuf::from("fixture"),
                    ),
                },
            );
        }
        append_application_until_waiting(&mut events, &command);
        (events, command)
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one scenario verifies the complete canonical child crash-prefix and tamper matrix"
    )]
    fn generic_child_application_is_ordered_recoverable_and_fail_closed() {
        let (mut events, mut command) = active_generic_children_fixture();
        for cut in 1..=events.len() {
            replay(events[..cut].iter()).expect("every crash prefix replays");
        }
        let initial = replay(events[..3].iter()).expect("initial spawn state");
        let first_proposal = plan_child_graph_application(&initial, &command)
            .expect("proposal plan")
            .events
            .into_iter()
            .next()
            .expect("proposal event");
        let mut tampered_proposal = first_proposal.clone();
        let RuntimeCommittedEvent::GenericChildCreationProposed(proposed) = &mut tampered_proposal
        else {
            panic!("generic proposal");
        };
        proposed.proposal.task = serde_json::json!({"instruction": "substituted"});
        assert!(matches!(
            reduce(Some(initial.clone()), &envelope(4, tampered_proposal)),
            Err(SessionReducerError::InvalidChildAgentTransition)
        ));
        let once =
            reduce(Some(initial), &envelope(4, first_proposal.clone())).expect("first proposal");
        assert!(matches!(
            reduce(Some(once), &envelope(5, first_proposal)),
            Err(SessionReducerError::InvalidChildAgentTransition)
        ));
        let active = replay(events.iter()).expect("active children");
        let tasks = active
            .child_agents
            .values()
            .map(|record| (record.identity.task_id.clone(), record.proposed_at.get()))
            .collect::<Vec<_>>();
        let mut tasks = tasks;
        tasks.sort();
        assert_eq!(tasks[0].0, "task-a");
        assert_eq!(tasks[1].0, "task-b");
        assert!(tasks[0].1 < tasks[1].1);

        for (index, record) in active.child_agents.values().enumerate() {
            let disposition = if index == 0 {
                GenericChildTerminalDisposition::Completed
            } else {
                GenericChildTerminalDisposition::Cancelled
            };
            let mut receipt = GenericChildTerminalReceipt {
                disposition,
                result_reference: (disposition == GenericChildTerminalDisposition::Completed)
                    .then(|| String::from("artifact-result-a")),
                artifact_references: BTreeSet::from([String::from("artifact-result")]),
                failure_code: None,
                receipt_hash: ContentHash::from_bytes([0; 32]),
            };
            let identity = record
                .generic_identity
                .as_deref()
                .expect("generic identity");
            let child_session_id = record.child_session_id.expect("child");
            let child_head_sequence = Sequence::new(40 + index as u64).expect("child head");
            receipt.receipt_hash = generic_child_terminal_receipt_hash(
                identity,
                child_session_id,
                child_head_sequence,
                &receipt,
            )
            .expect("terminal hash");
            command.evidence.terminals.insert(
                record.identity.task_id.clone(),
                ChildTerminalEvidence {
                    child_session_id,
                    child_head_sequence,
                    disposition,
                    result_reference: receipt.result_reference,
                    artifact_references: receipt.artifact_references,
                    failure_code: None,
                    receipt_hash: receipt.receipt_hash,
                },
            );
        }
        append_application_until_waiting(&mut events, &command);
        let terminal = replay(events.iter()).expect("terminal replay");
        assert!(
            terminal
                .child_agents
                .values()
                .any(|record| { record.state == ChildAgentState::Cancelled })
        );
        assert!(
            plan_child_graph_application(&terminal, &command)
                .expect("idempotent plan")
                .events
                .is_empty()
        );

        let mut substituted = command.clone();
        substituted
            .evidence
            .terminals
            .get_mut("task-a")
            .expect("terminal")
            .receipt_hash = ContentHash::digest(b"substituted receipt");
        assert!(matches!(
            plan_child_graph_application(&active, &substituted),
            Err(crate::child_graph_application::ChildGraphApplicationError::Substitution)
        ));
    }

    fn enter_generic_wait(events: &mut Vec<EventEnvelope<RuntimeCommittedEvent>>) -> SessionState {
        let next = events.last().expect("event").metadata.sequence.get() + 1;
        events.push(envelope(
            next,
            RuntimeCommittedEvent::StyleNodeCompleted(StyleNodeCompletedEvent {
                node_id: String::from("commission"),
                attempt: 1,
                loop_iteration: 0,
                step: 1,
                result_reference: Some(String::from("children:2")),
                artifact_reference: None,
            }),
        ));
        events.push(envelope(
            next + 1,
            RuntimeCommittedEvent::StyleTransitionSelected(StyleTransitionSelectedEvent {
                from_node_id: String::from("commission"),
                to_node_id: String::from("rendezvous"),
                attempt: 1,
                loop_iteration: 0,
                step: 1,
            }),
        ));
        events.push(envelope(
            next + 2,
            RuntimeCommittedEvent::StyleNodeEntered(StyleNodeEnteredEvent {
                node_id: String::from("rendezvous"),
                attempt: 1,
                loop_iteration: 0,
                step: 2,
            }),
        ));
        replay(events.iter()).expect("wait entered")
    }

    fn completed_generic_wait_fixture() -> (
        Vec<EventEnvelope<RuntimeCommittedEvent>>,
        PlanChildGraphApplicationCommand,
        ContentHash,
    ) {
        let (mut events, mut spawn_command) = active_generic_children_fixture();
        let active = enter_generic_wait(&mut events);
        for (index, record) in active.child_agents.values().enumerate() {
            let identity = record
                .generic_identity
                .as_deref()
                .expect("generic identity");
            let child_session_id = record.child_session_id.expect("child");
            let child_head_sequence = Sequence::new(50 + index as u64).expect("child head");
            let mut receipt = GenericChildTerminalReceipt {
                disposition: GenericChildTerminalDisposition::Completed,
                result_reference: Some(format!("child-result-{index}")),
                artifact_references: BTreeSet::from([format!("child-artifact-{index}")]),
                failure_code: None,
                receipt_hash: ContentHash::from_bytes([0; 32]),
            };
            receipt.receipt_hash = generic_child_terminal_receipt_hash(
                identity,
                child_session_id,
                child_head_sequence,
                &receipt,
            )
            .expect("terminal hash");
            spawn_command.evidence.terminals.insert(
                record.identity.task_id.clone(),
                ChildTerminalEvidence {
                    child_session_id,
                    child_head_sequence,
                    disposition: GenericChildTerminalDisposition::Completed,
                    result_reference: receipt.result_reference,
                    artifact_references: receipt.artifact_references,
                    failure_code: None,
                    receipt_hash: receipt.receipt_hash,
                },
            );
        }
        append_application_until_waiting(&mut events, &spawn_command);
        let terminal = replay(events.iter()).expect("terminal children");
        let mut successful = terminal
            .child_agents
            .values()
            .map(|record| {
                let receipt = record
                    .terminal_receipt
                    .as_deref()
                    .expect("terminal receipt");
                ChildWaitSuccess {
                    child_id: record.child_session_id.expect("child"),
                    task_id: record.identity.task_id.clone(),
                    result_reference: receipt.result_reference.clone().expect("result reference"),
                    artifact_references: receipt.artifact_references.clone(),
                    completion_sequence: record.completed_at.expect("completion").get(),
                }
            })
            .collect::<Vec<_>>();
        successful.sort_by_key(|success| success.child_id);
        let unsuccessful = Vec::<ChildWaitFailure>::new();
        let result_hash = ContentHash::digest(
            &serde_json::to_vec(&("completed", &successful, &unsuccessful)).expect("wait result"),
        );
        let execution = terminal.style_execution.as_ref().expect("execution");
        let contract = execution.execution_contract.as_deref().expect("contract");
        let resolution = contract
            .node_executors
            .iter()
            .find(|resolution| resolution.node_id == "rendezvous")
            .expect("wait resolution");
        let command = PlanChildGraphApplicationCommand {
            session_id: session_id(),
            work: NodeWorkIdentity {
                run_id: contract.run_id.clone(),
                node_id: String::from("rendezvous"),
                branch_path: Vec::new(),
                attempt: 1,
                loop_iteration: 0,
                step: 2,
            },
            execution_plan_hash: contract.execution_plan_hash,
            configuration_hash: resolution.adapter_configuration_reference,
            outcome: ChildGraphNodeOutcome::Wait(ChildWaitProjection::Completed {
                successful,
                unsuccessful,
                result_hash,
            }),
            evidence: ChildGraphApplicationEvidence::default(),
        };
        append_application_until_waiting(&mut events, &command);
        (events, command, result_hash)
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one scenario compares completed, cancelled, timed-out, and failed wait replay projections"
    )]
    fn generic_child_wait_replays_completed_cancellation_and_timeout_exactly() {
        let (events, command, result_hash) = completed_generic_wait_fixture();
        let completed = replay(events.iter()).expect("completed wait");
        let wait = completed
            .planner_worker
            .child_waits
            .values()
            .next()
            .expect("wait projection");
        assert_eq!(
            wait.projection.disposition,
            GenericChildWaitDisposition::Completed
        );
        assert_eq!(wait.projection.result_hash, Some(result_hash));
        assert!(
            plan_child_graph_application(&completed, &command)
                .expect("duplicate wait")
                .events
                .is_empty()
        );

        let (mut cancellation_events, _) = active_generic_children_fixture();
        let cancellation_state = enter_generic_wait(&mut cancellation_events);
        let contract = cancellation_state
            .style_execution
            .as_ref()
            .and_then(|execution| execution.execution_contract.as_deref())
            .expect("contract");
        let resolution = contract
            .node_executors
            .iter()
            .find(|resolution| resolution.node_id == "rendezvous")
            .expect("wait resolution");
        let mut child_ids = cancellation_state
            .child_agents
            .values()
            .filter_map(|record| record.child_session_id)
            .collect::<Vec<_>>();
        child_ids.sort();
        let cancellation_hash = ContentHash::digest(
            &serde_json::to_vec(&("parent_cancelled", &child_ids, false)).expect("cancellation"),
        );
        let command_for = |projection| PlanChildGraphApplicationCommand {
            session_id: session_id(),
            work: NodeWorkIdentity {
                run_id: contract.run_id.clone(),
                node_id: String::from("rendezvous"),
                branch_path: Vec::new(),
                attempt: 1,
                loop_iteration: 0,
                step: 2,
            },
            execution_plan_hash: contract.execution_plan_hash,
            configuration_hash: resolution.adapter_configuration_reference,
            outcome: ChildGraphNodeOutcome::Wait(projection),
            evidence: ChildGraphApplicationEvidence::default(),
        };
        let cancellation = command_for(ChildWaitProjection::Failed {
            code: String::from("parent_cancelled"),
            cancel_children: child_ids,
            detached: false,
            result_hash: cancellation_hash,
        });
        let cancellation_event = plan_child_graph_application(&cancellation_state, &cancellation)
            .expect("cancellation plan")
            .events
            .into_iter()
            .next()
            .expect("cancellation event");
        let cancellation_projection = reduce(
            Some(cancellation_state.clone()),
            &envelope(
                cancellation_state.last_sequence.get() + 1,
                cancellation_event,
            ),
        )
        .expect("cancellation projection");
        assert_eq!(
            cancellation_projection
                .planner_worker
                .child_waits
                .values()
                .next()
                .expect("wait")
                .projection
                .failure_code
                .as_deref(),
            Some("parent_cancelled")
        );

        let timeout_hash = ContentHash::digest(
            &serde_json::to_vec(&("child_wait_timeout", Vec::<SessionId>::new(), false))
                .expect("timeout"),
        );
        let timeout = command_for(ChildWaitProjection::Failed {
            code: String::from("child_wait_timeout"),
            cancel_children: Vec::new(),
            detached: false,
            result_hash: timeout_hash,
        });
        let timeout_event = plan_child_graph_application(&cancellation_state, &timeout)
            .expect("timeout plan")
            .events
            .into_iter()
            .next()
            .expect("timeout event");
        reduce(
            Some(cancellation_state.clone()),
            &envelope(cancellation_state.last_sequence.get() + 1, timeout_event),
        )
        .expect("timeout projection");

        let mut tampered = timeout.clone();
        let ChildGraphNodeOutcome::Wait(ChildWaitProjection::Failed { result_hash, .. }) =
            &mut tampered.outcome
        else {
            panic!("failed wait");
        };
        *result_hash = ContentHash::digest(b"tampered wait");
        let tampered_event = plan_child_graph_application(&cancellation_state, &tampered)
            .expect("application preserves pure evidence")
            .events
            .into_iter()
            .next()
            .expect("tampered event");
        assert!(matches!(
            reduce(
                Some(cancellation_state.clone()),
                &envelope(cancellation_state.last_sequence.get() + 1, tampered_event)
            ),
            Err(SessionReducerError::InvalidPlannerWorkerTransition)
        ));
    }

    fn generic_review_base() -> (
        Vec<EventEnvelope<RuntimeCommittedEvent>>,
        SessionState,
        NodeWorkIdentity,
        ContentHash,
        ContentHash,
    ) {
        let (mut events, _, wait_hash) = completed_generic_wait_fixture();
        let next = events.last().expect("event").metadata.sequence.get() + 1;
        events.push(envelope(
            next,
            RuntimeCommittedEvent::StyleNodeCompleted(StyleNodeCompletedEvent {
                node_id: String::from("rendezvous"),
                attempt: 1,
                loop_iteration: 0,
                step: 2,
                result_reference: Some(format!("child-wait:{wait_hash}")),
                artifact_reference: None,
            }),
        ));
        events.push(envelope(
            next + 1,
            RuntimeCommittedEvent::StyleTransitionSelected(StyleTransitionSelectedEvent {
                from_node_id: String::from("rendezvous"),
                to_node_id: String::from("quality-gate"),
                attempt: 1,
                loop_iteration: 0,
                step: 2,
            }),
        ));
        events.push(envelope(
            next + 2,
            RuntimeCommittedEvent::StyleNodeEntered(StyleNodeEnteredEvent {
                node_id: String::from("quality-gate"),
                attempt: 1,
                loop_iteration: 0,
                step: 3,
            }),
        ));
        let state = replay(events.iter()).expect("review entered");
        let contract = state
            .style_execution
            .as_ref()
            .and_then(|execution| execution.execution_contract.as_deref())
            .expect("contract");
        let resolution = contract
            .node_executors
            .iter()
            .find(|resolution| resolution.node_id == "quality-gate")
            .expect("review resolution");
        let run_id = contract.run_id.clone();
        let execution_plan_hash = contract.execution_plan_hash;
        let configuration_hash = resolution.adapter_configuration_reference;
        (
            events,
            state,
            NodeWorkIdentity {
                run_id,
                node_id: String::from("quality-gate"),
                branch_path: Vec::new(),
                attempt: 1,
                loop_iteration: 0,
                step: 3,
            },
            execution_plan_hash,
            configuration_hash,
        )
    }

    #[test]
    fn generic_review_routes_revision_approval_and_failure_without_substitution() {
        let (_, base, work, execution_plan_hash, configuration_hash) = generic_review_base();
        let finding = ReviewFinding {
            code: String::from("review-evidence"),
            message: String::from("bounded reviewer evidence"),
            artifact_references: BTreeSet::from([String::from("artifact-evidence")]),
        };
        for (disposition, destination, revision, next_revision, rejected) in [
            (ReviewDisposition::Approved, "accepted", 0, None, Vec::new()),
            (
                ReviewDisposition::Revision,
                "revise",
                0,
                Some(1),
                vec![String::from("task-a")],
            ),
            (
                ReviewDisposition::Failed,
                "rejected",
                3,
                None,
                vec![String::from("task-b")],
            ),
        ] {
            let command = PlanChildGraphApplicationCommand {
                session_id: session_id(),
                work: work.clone(),
                execution_plan_hash,
                configuration_hash,
                outcome: ChildGraphNodeOutcome::Review(ReviewRoutingProposal {
                    disposition,
                    destination_node_id: destination.to_owned(),
                    current_revision: revision,
                    next_revision,
                    rejected_task_ids: rejected,
                    findings: vec![finding.clone()],
                    evidence_hash: ContentHash::digest(destination.as_bytes()),
                }),
                evidence: ChildGraphApplicationEvidence::default(),
            };
            let event = plan_child_graph_application(&base, &command)
                .expect("review plan")
                .events
                .into_iter()
                .next()
                .expect("review event");
            let routed = reduce(
                Some(base.clone()),
                &envelope(base.last_sequence.get() + 1, event),
            )
            .expect("review route");
            assert!(
                plan_child_graph_application(&routed, &command)
                    .expect("idempotent review")
                    .events
                    .is_empty()
            );
        }

        let revision = PlanChildGraphApplicationCommand {
            session_id: session_id(),
            work,
            execution_plan_hash,
            configuration_hash,
            outcome: ChildGraphNodeOutcome::Review(ReviewRoutingProposal {
                disposition: ReviewDisposition::Revision,
                destination_node_id: String::from("revise"),
                current_revision: 0,
                next_revision: Some(1),
                rejected_task_ids: vec![String::from("task-a")],
                findings: vec![finding],
                evidence_hash: ContentHash::digest(b"revision"),
            }),
            evidence: ChildGraphApplicationEvidence::default(),
        };
        let mut tampered = plan_child_graph_application(&base, &revision)
            .expect("review plan")
            .events
            .into_iter()
            .next()
            .expect("review event");
        let RuntimeCommittedEvent::GenericReviewRouted(event) = &mut tampered else {
            panic!("generic review event");
        };
        event.evidence.destination_node_id = String::from("accepted");
        event.evidence.application_hash =
            generic_review_application_hash(event).expect("tampered hash");
        assert!(matches!(
            reduce(
                Some(base.clone()),
                &envelope(base.last_sequence.get() + 1, tampered)
            ),
            Err(SessionReducerError::InvalidPlannerWorkerTransition)
        ));
    }

