    #[test]
    fn style_initialization_derives_typed_variables_and_condition_state() {
        let graph = canonical_variable_graph();
        let style_binding = binding(BuiltInStyle::PersistentChat);
        let mut contract = test_execution_contract(&style_binding, &graph);
        contract.initial_variables_json = String::from(r#"{"ready":true}"#);
        let reducer = initialize_canonical_variables(session_id(), &graph, Some(&contract))
            .expect("derived variable reducer");
        assert_eq!(
            reducer.environment().canonical_entries()["ready"].value,
            CanonicalVariableValue::Boolean(true)
        );
        assert_eq!(
            reducer.environment().classify_condition(
                "ready == true",
                &VariableReader {
                    node_id: String::from("start"),
                    branch_id: None,
                },
                &[String::from("ready")].into_iter().collect(),
                agentmod_expression_engine::ExpressionLimits::default(),
            ),
            ConditionEligibility::Eligible
        );
        reducer
            .validate_replayed()
            .expect("pure restart validation");
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one journal fixture proves declaration, assignment, failed validation, restart, event mapping, condition reconstruction, and tamper rejection"
    )]
    fn canonical_variable_events_replay_restart_and_reject_tampering() {
        let graph = canonical_variable_graph();
        let mut events = vec![
            created(),
            envelope(
                2,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(graph.clone()),
                        input_reference: None,
                        execution_contract: None,
                    },
                )),
            ),
        ];
        let initialized = replay(&events).expect("initialized state");
        let reducer = initialized
            .style_execution
            .as_ref()
            .and_then(|execution| execution.canonical_variables.as_deref())
            .expect("canonical variable projection");
        let declared = reducer
            .prepare_event(
                "runtime",
                VariableValidationAttempt::Declare {
                    declaration: graph.variables[0].clone(),
                },
            )
            .expect("declaration event");
        let declared_payload = RuntimeCommittedEvent::from(declared);
        assert_eq!(declared_payload.event_type(), "graph.variable_declared");
        assert!(declared_payload.canonical_variable_event().is_some());
        events.push(envelope(3, declared_payload));

        let declared_state = replay(&events).expect("declared replay");
        let reducer = declared_state
            .style_execution
            .as_ref()
            .and_then(|execution| execution.canonical_variables.as_deref())
            .expect("declared projection");
        let assigned = reducer
            .prepare_event(
                "runtime",
                VariableValidationAttempt::Assign {
                    variable: String::from("ready"),
                    writer: VariableWriter::Runtime,
                    expected_version: None,
                    value: CanonicalVariableValue::Boolean(true),
                },
            )
            .expect("assignment event");
        let assigned_payload = RuntimeCommittedEvent::from(assigned.clone());
        assert_eq!(assigned_payload.event_type(), "graph.variable_assigned");
        let CanonicalVariableEvent::Assigned(assigned_event) = &assigned else {
            panic!("assigned event");
        };
        assert_eq!(
            RuntimeCommittedEvent::VariableMerged(Box::new(VariableMergedEvent {
                binding: assigned_event.binding.clone(),
                writer: VariableWriter::Runtime,
                policy: agentmod_graph_engine::VariableMergePolicy::FirstBranch,
                branches: Vec::new(),
                value: CanonicalVariableValue::Boolean(true),
            }))
            .event_type(),
            "graph.variable_merged"
        );
        assert_eq!(
            RuntimeCommittedEvent::VariableRemoved(Box::new(VariableRemovedEvent {
                binding: assigned_event.binding.clone(),
                writer: VariableWriter::Runtime,
            }))
            .event_type(),
            "graph.variable_removed"
        );
        events.push(envelope(4, assigned_payload));

        let assigned_state = replay(&events).expect("assigned replay");
        let reducer = assigned_state
            .style_execution
            .as_ref()
            .and_then(|execution| execution.canonical_variables.as_deref())
            .expect("assigned projection");
        let failed = reducer
            .prepare_event(
                "runtime",
                VariableValidationAttempt::Assign {
                    variable: String::from("ready"),
                    writer: VariableWriter::Runtime,
                    expected_version: None,
                    value: CanonicalVariableValue::Boolean(false),
                },
            )
            .expect("validation failure");
        assert!(matches!(
            failed,
            CanonicalVariableEvent::ValidationFailed(ref failure)
                if failure.code == VariableValidationFailureCode::VersionConflict
        ));
        let failed_payload = RuntimeCommittedEvent::from(failed);
        assert_eq!(
            failed_payload.event_type(),
            "graph.variable_validation_failed"
        );
        events.push(envelope(5, failed_payload));

        let replayed = replay(&events).expect("complete variable replay");
        let reducer = replayed
            .style_execution
            .as_ref()
            .and_then(|execution| execution.canonical_variables.as_deref())
            .expect("replayed projection");
        assert_eq!(reducer.validation_failures().len(), 1);
        assert_eq!(
            reducer.environment().classify_condition(
                "ready",
                &VariableReader {
                    node_id: String::from("start"),
                    branch_id: None,
                },
                &[String::from("ready")].into_iter().collect(),
                agentmod_expression_engine::ExpressionLimits::default(),
            ),
            ConditionEligibility::Eligible
        );
        let serialized =
            serde_json::to_vec(replayed.style_execution.as_ref().expect("style execution"))
                .expect("serialize execution");
        let recovered: StyleExecutionState =
            serde_json::from_slice(&serialized).expect("deserialize execution");
        recovered
            .canonical_variables
            .as_deref()
            .expect("recovered projection")
            .validate_replayed()
            .expect("restart validation");

        let mut tampered = assigned;
        let CanonicalVariableEvent::Assigned(event) = &mut tampered else {
            panic!("assigned event");
        };
        event.binding.value_hash = Some(ContentHash::digest(b"tampered"));
        let mut tampered_events = events[..3].to_vec();
        tampered_events.push(envelope(4, RuntimeCommittedEvent::from(tampered)));
        assert!(matches!(
            replay(&tampered_events),
            Err(SessionReducerError::CanonicalVariable(
                VariableEnvironmentError::EventMismatch
            ))
        ));
    }

    #[test]
    fn legacy_initial_variables_and_projection_defaults_remain_replayable() {
        let style_binding = binding_for_version(BuiltInStyle::PersistentChat, "1.1.0");
        let compiled: CompiledSessionStyle =
            serde_json::from_str(&style_binding.compiled_style_json).expect("compiled style");
        assert!(compiled.graph.variables.is_empty());
        let mut contract = test_execution_contract(&style_binding, &compiled.graph);
        contract.initial_variables_json = String::from(r#"{"legacy_counter":7}"#);
        let events = vec![
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: style_binding.id.clone(),
                    style_binding: Some(Box::new(style_binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(compiled.graph),
                        input_reference: None,
                        execution_contract: Some(Box::new(contract)),
                    },
                )),
            ),
        ];
        let state = replay(&events).expect("legacy initial variables replay");
        let execution = state.style_execution.expect("style execution");
        assert!(
            execution
                .canonical_variables
                .as_deref()
                .expect("empty canonical projection")
                .environment()
                .canonical_entries()
                .is_empty()
        );
        assert_eq!(
            execution
                .execution_contract
                .as_deref()
                .expect("legacy contract")
                .initial_variables_json,
            r#"{"legacy_counter":7}"#
        );

        let mut serialized = serde_json::to_value(&execution).expect("serialize state");
        serialized
            .as_object_mut()
            .expect("state object")
            .remove("canonical_variables");
        let legacy: StyleExecutionState =
            serde_json::from_value(serialized).expect("legacy state default");
        assert!(legacy.canonical_variables.is_none());
    }

