    fn ephemeral_context_graph() -> ExecutableGraph {
        compile_graph(
            r#"
format_version = 1
entry = "fresh-context"
[budget]
max_steps = 10
max_tokens = 100
max_cost_micros = 100
max_duration_ms = 1000
[declarations]
capabilities = ["context", "model"]
providers = ["mock"]
[[nodes]]
id = "fresh-context"
kind = "context_transform"
[[nodes]]
id = "respond"
kind = "model_call"
provider = "mock"
[[nodes]]
id = "done"
kind = "complete_turn"
[[edges]]
from = "fresh-context"
to = "respond"
[[edges]]
from = "respond"
to = "done"
"#,
            &GraphCacheInputs {
                plugin_set_hash: ContentHash::digest(b"plugins"),
                runtime_api_version: "1.0.0".into(),
                capability_set: BTreeSet::from([String::from("context"), String::from("model")]),
            },
            CompilerLimits::default(),
        )
        .expect("ephemeral context graph")
    }

    fn artifact_graph() -> ExecutableGraph {
        compile_graph(
            r#"
format_version = 1
entry = "persist"
[budget]
max_steps = 10
max_tokens = 100
max_cost_micros = 100
max_duration_ms = 1000
[declarations]
capabilities = ["artifacts"]
[[nodes]]
id = "persist"
kind = "persist_artifact"
configuration = { type = "persist_artifact", content = { kind = "static_json", value = { finding = "bounded" } }, mime_type = "application/json", security = "private", retention = "session" }
[[nodes]]
id = "done"
kind = "complete_session"
[[edges]]
from = "persist"
to = "done"
"#,
            &GraphCacheInputs {
                plugin_set_hash: ContentHash::digest(b"plugins"),
                runtime_api_version: "1.0.0".into(),
                capability_set: BTreeSet::from([String::from("artifacts")]),
            },
            CompilerLimits::default(),
        )
        .expect("artifact graph")
    }

    fn artifact_identity() -> ArtifactPersistenceIdentity {
        let mut identity = ArtifactPersistenceIdentity {
            execution_id: String::new(),
            proposal_id: EventId::from_uuid(Uuid::from_u128(104)).to_string(),
            node_id: String::from("persist"),
            branch_path: Vec::new(),
            attempt: 1,
            loop_iteration: 0,
            step: 1,
            context_phase: None,
            content_hash: ContentHash::digest(br#"{"finding":"bounded"}"#),
        };
        identity.execution_id =
            artifact_persistence_execution_id(&identity).expect("artifact execution identity");
        identity
    }

    fn artifact_action_digest(
        identity: &ArtifactPersistenceIdentity,
        mime_type: &str,
        byte_size: u64,
    ) -> ContentHash {
        ActionProposal {
            id: ProposalId(identity.proposal_id.clone()),
            action: ConsequentialAction::ArtifactPersistence(ArtifactPersistenceAction {
                content_hash: identity.content_hash,
                mime_type: mime_type.to_owned(),
                byte_size,
                security: ArtifactPersistenceSecurity::Private,
                retention: ArtifactPersistenceRetention::Session,
            }),
            style: String::from("persistent-chat"),
            workspace: String::from("fixture"),
            origin: String::from("runtime.style"),
        }
        .digest()
        .expect("artifact action digest")
    }

