    fn plugin_memory_context_state() -> (SessionState, ContextPhaseIdentity) {
        let mut style_binding = binding(BuiltInStyle::PersistentChat);
        style_binding.memory.provider = String::from("fixture.memory");
        style_binding.memory.plugin = Some(SessionPluginMemoryConfiguration {
            plugin_id: String::from("fixture.context"),
            plugin_version: String::from("2.3.4"),
            provider_id: String::from("fixture.memory"),
            provider_version: String::from("1.4.0"),
            declaration_hash: ContentHash::digest(b"memory declaration"),
            configuration_reference: ContentHash::digest(b"memory configuration"),
        });
        style_binding.memory.scopes = vec![String::from("session")];
        style_binding.memory.retrieval_timing = String::from("turn_start");
        style_binding.memory.max_items = 4;
        style_binding.memory.max_injected_bytes = 16 * 1024;
        let graph = context_graph();
        let mut compiled: CompiledSessionStyle =
            serde_json::from_str(&style_binding.compiled_style_json).expect("compiled style");
        compiled.graph = graph.clone();
        style_binding.compiled_style_json =
            serde_json::to_string(&compiled).expect("compiled style JSON");
        style_binding.execution_plan = None;
        style_binding.execution_plan_hash = None;
        let boundary = context_identity("turn_start", 5, ContextBoundaryOrigin::UserTurn);
        let phase = context_phase(&boundary, "memory");
        let state = replay(&[
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: style_binding.id.clone(),
                    style_binding: Some(Box::new(style_binding.clone())),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::ConversationEntryCommitted(
                    ConversationEntryCommittedEvent {
                        entry: ConversationEntry::UserMessage(TextEntry {
                            id: ConversationEntryId(String::from("user:plugin-memory")),
                            text: String::from("preserve this current input"),
                            source_sequence: Sequence::new(2).expect("sequence"),
                        }),
                    },
                ),
            ),
            envelope(
                3,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(graph),
                        input_reference: None,
                        execution_contract: None,
                    },
                )),
            ),
            envelope(
                4,
                RuntimeCommittedEvent::StyleNodeEntered(StyleNodeEnteredEvent {
                    node_id: String::from("respond"),
                    attempt: 1,
                    loop_iteration: 0,
                    step: 1,
                }),
            ),
            envelope(
                5,
                RuntimeCommittedEvent::PluginSetActivated(PluginSetActivatedEvent {
                    plugin_ids: vec![String::from("fixture.context")],
                    plugin_set_hash: style_binding.plugin_set_hash,
                }),
            ),
            envelope(
                6,
                RuntimeCommittedEvent::ContextBoundaryStarted(ContextBoundaryStartedEvent {
                    identity: boundary,
                }),
            ),
            envelope(
                7,
                RuntimeCommittedEvent::ContextPhaseStarted(ContextPhaseStartedEvent {
                    identity: phase.clone(),
                }),
            ),
        ])
        .expect("plugin memory context state");
        (state, phase)
    }

    fn plugin_memory_request() -> PluginContextOperationRequest {
        PluginContextOperationRequest::MemoryRetrieve {
            query: String::from("current request"),
            scopes: vec![format!("session:{}", session_id())],
            max_items: 4,
            max_injected_bytes: 16 * 1024,
        }
    }

    fn plugin_context_operation_inputs_json(
        readable_state: &serde_json::Value,
    ) -> serde_json::Value {
        serde_json::json!({
            "readable_state": readable_state,
            "artifacts": [],
            "references": [],
            "parameters": {}
        })
    }

    fn plugin_memory_replacement(
        identity: &PluginContextOperationIdentity,
        receipt_hash: ContentHash,
        injection_sequence: u64,
    ) -> (Vec<ConversationEntry>, Vec<ConversationEntryId>) {
        let id = ConversationEntryId(String::from("plugin-memory:item-1"));
        let entry = ConversationEntry::RetrievedMemory(crate::conversation::RetrievedMemoryEntry {
            id: id.clone(),
            provider: identity.implementation_id.clone(),
            query: String::from("current request"),
            scope: format!("session:{}", session_id()),
            source: String::from("fixture.context"),
            reference: String::from("memory:item-1"),
            score: Some(0.95),
            content: String::from("bounded retrieved value"),
            injection_sequence: Sequence::new(injection_sequence).expect("injection sequence"),
            injection_event: Some(EventId::from_uuid(Uuid::from_u128(
                100 + u128::from(injection_sequence),
            ))),
            created_at_millis: 1_700_000_000_000,
            size_bytes: 23,
            typed_provenance: Some(Box::new(
                crate::conversation::RetrievedMemoryTypedProvenance {
                    value: Some(serde_json::json!({"text": "bounded retrieved value"})),
                    value_hash: bounded_json_hash(
                        &serde_json::json!({"text": "bounded retrieved value"}),
                        MAX_PLUGIN_CONTEXT_OPERATION_BYTES,
                    )
                    .expect("typed value hash"),
                    artifact: None,
                    references: Vec::new(),
                    security_classification: String::from("private"),
                    plugin_invocation_id: identity.invocation_id.clone(),
                    plugin_terminal_receipt_hash: receipt_hash,
                },
            )),
        });
        (vec![entry], vec![id])
    }

    fn authorize_plugin_context_operation(
        state: SessionState,
        identity: &PluginContextOperationIdentity,
        sequence: u64,
    ) -> SessionState {
        let request = state
            .plugin_context_operations
            .get(&identity.invocation_id)
            .expect("operation")
            .request
            .clone();
        let action_digest = plugin_context_operation_action_proposal(&state, identity, &request)
            .expect("action")
            .digest()
            .expect("action digest");
        reduce(
            Some(state),
            &envelope(
                sequence,
                RuntimeCommittedEvent::PluginContextOperationAuthorized(Box::new(
                    PluginContextOperationAuthorizedEvent {
                        identity: identity.clone(),
                        action_digest,
                        authorization_digest: plugin_context_operation_authorization_digest(
                            identity,
                            action_digest,
                        ),
                    },
                )),
            ),
        )
        .expect("authorized operation")
    }

    fn proposed_plugin_memory_operation() -> (SessionState, PluginContextOperationIdentity) {
        let (state, phase) = plugin_memory_context_state();
        let request = plugin_memory_request();
        let readable_state = plugin_context_operation_inputs_json(&serde_json::json!({}));
        let identity = plugin_context_operation_identity(&state, phase, &request, &readable_state)
            .expect("operation identity");
        let proposed = reduce(
            Some(state),
            &envelope(
                8,
                RuntimeCommittedEvent::PluginContextOperationProposed(Box::new(
                    PluginContextOperationProposedEvent {
                        identity: identity.clone(),
                        request,
                        readable_state,
                    },
                )),
            ),
        )
        .expect("proposed");
        (proposed, identity)
    }

    fn completed_plugin_memory_operation() -> (
        SessionState,
        PluginContextOperationIdentity,
        ContentHash,
        ContentHash,
        ContentHash,
    ) {
        let (proposed, identity) = proposed_plugin_memory_operation();
        let authorized = authorize_plugin_context_operation(proposed, &identity, 9);
        let action_digest = authorized.plugin_context_operations[&identity.invocation_id]
            .action_digest
            .expect("action digest");
        let dispatched = reduce(
            Some(authorized),
            &envelope(
                10,
                RuntimeCommittedEvent::PluginContextOperationDispatched(Box::new(
                    PluginContextOperationDispatchedEvent {
                        identity: identity.clone(),
                        action_digest,
                    },
                )),
            ),
        )
        .expect("dispatched");
        let receipt = SealedPluginContextReceipt {
            receipt_hash: ContentHash::digest(b"approval terminal receipt"),
            receipt_reference: String::from("plugin-receipt:approval:1"),
        };
        let (retrieved, retrieved_entry_ids) =
            plugin_memory_replacement(&identity, receipt.receipt_hash, 11);
        let mut replacement = dispatched.conversation.provider_projection().to_vec();
        replacement.extend(retrieved);
        let proposal = PluginContextOperationProposal::MemoryRetrieve {
            replacement: replacement.clone(),
            retrieved_entry_ids,
        };
        let proposal_hash = bounded_json_hash(&proposal, MAX_PLUGIN_CONTEXT_OPERATION_BYTES)
            .expect("proposal hash");
        let completed = reduce(
            Some(dispatched),
            &envelope(
                11,
                RuntimeCommittedEvent::PluginContextOperationCompleted(Box::new(
                    PluginContextOperationCompletedEvent {
                        identity: identity.clone(),
                        proposal,
                        proposal_hash,
                        terminal_receipt: receipt,
                    },
                )),
            ),
        )
        .expect("completed");
        let replacement_hash = bounded_json_hash(&replacement, MAX_PLUGIN_CONTEXT_OPERATION_BYTES)
            .expect("replacement hash");
        let binding = completed.style_binding.as_ref().expect("binding");
        let application_digest = context_replacement_action_proposal(
            &binding.id,
            &completed.workspace,
            &identity.phase.boundary.run_id,
            &identity.phase.phase,
            replacement_hash,
        )
        .digest()
        .expect("application digest");
        (
            completed,
            identity,
            proposal_hash,
            replacement_hash,
            application_digest,
        )
    }

    #[test]
    fn plugin_context_operation_failure_and_ambiguity_are_terminal() {
        let (proposed, identity) = proposed_plugin_memory_operation();
        let denied = reduce(
            Some(proposed.clone()),
            &envelope(
                9,
                RuntimeCommittedEvent::PluginContextOperationFailed(Box::new(
                    PluginContextOperationFailedEvent {
                        identity: identity.clone(),
                        action_digest: None,
                        code: String::from("policy_denied"),
                        terminal_receipt: None,
                    },
                )),
            ),
        )
        .expect("pre-dispatch failure");
        assert_eq!(
            classify_plugin_context_operation_recovery(&denied, &identity.invocation_id, None),
            PluginContextOperationRecovery::TerminallyFailed
        );

        let authorized = authorize_plugin_context_operation(proposed, &identity, 9);
        let action_digest = authorized.plugin_context_operations[&identity.invocation_id]
            .action_digest
            .expect("action digest");
        let dispatched = reduce(
            Some(authorized),
            &envelope(
                10,
                RuntimeCommittedEvent::PluginContextOperationDispatched(Box::new(
                    PluginContextOperationDispatchedEvent {
                        identity: identity.clone(),
                        action_digest,
                    },
                )),
            ),
        )
        .expect("dispatched");
        assert!(matches!(
            reduce(
                Some(dispatched.clone()),
                &envelope(
                    11,
                    RuntimeCommittedEvent::PluginContextOperationFailed(Box::new(
                        PluginContextOperationFailedEvent {
                            identity: identity.clone(),
                            action_digest: None,
                            code: String::from("unproven_failure"),
                            terminal_receipt: None,
                        },
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidPluginContextOperation)
        ));
        let ambiguous = reduce(
            Some(dispatched),
            &envelope(
                11,
                RuntimeCommittedEvent::PluginContextOperationAmbiguous(Box::new(
                    PluginContextOperationAmbiguousEvent {
                        identity: identity.clone(),
                        code: String::from("terminal_receipt_missing"),
                        terminal_receipt: None,
                    },
                )),
            ),
        )
        .expect("ambiguous");
        assert_eq!(
            classify_plugin_context_operation_recovery(&ambiguous, &identity.invocation_id, None),
            PluginContextOperationRecovery::AmbiguousFailClosed
        );
    }

    #[test]
    fn plugin_context_invocation_approval_link_advances_exact_phase_without_rebinding() {
        let (proposed, identity) = proposed_plugin_memory_operation();
        let request = proposed.plugin_context_operations[&identity.invocation_id]
            .request
            .clone();
        let action_digest =
            plugin_context_operation_action_proposal(&proposed, &identity, &request)
                .expect("proposal")
                .digest()
                .expect("digest");
        let approval_id = continuation_id();
        let subject = ApprovalSubject::PluginContextOperation {
            invocation_id: identity.invocation_id.clone(),
            invocation_digest: identity.invocation_digest,
            stage: PluginContextApprovalStage::Invocation,
            action_digest,
            proposal_hash: None,
            replacement_hash: None,
        };
        let requested = reduce(
            Some(proposed),
            &envelope(
                9,
                RuntimeCommittedEvent::ApprovalRequested(ApprovalRequestedEvent {
                    continuation_id: approval_id,
                    action_summary: String::from("invoke plugin memory"),
                    subject: Some(subject),
                }),
            ),
        )
        .expect("linked request");
        assert_eq!(
            requested.plugin_context_operations[&identity.invocation_id].last_sequence,
            Sequence::new(9).expect("sequence")
        );
        let resolved = reduce(
            Some(requested),
            &envelope(
                10,
                RuntimeCommittedEvent::ApprovalResolved(ApprovalResolvedEvent {
                    continuation_id: approval_id,
                    approved: true,
                }),
            ),
        )
        .expect("linked resolution");
        let authorized = authorize_plugin_context_operation(resolved, &identity, 11);
        assert_eq!(
            authorized.plugin_context_operations[&identity.invocation_id].state,
            PluginContextOperationState::Authorized
        );
    }

    #[test]
    fn plugin_context_application_denial_is_exact_and_preserves_terminal_evidence() {
        let (completed, identity, proposal_hash, replacement_hash, action_digest) =
            completed_plugin_memory_operation();
        assert!(matches!(
            reduce(
                Some(completed.clone()),
                &envelope(
                    12,
                    RuntimeCommittedEvent::PluginContextOperationFailed(Box::new(
                        PluginContextOperationFailedEvent {
                            identity: identity.clone(),
                            action_digest: Some(action_digest),
                            code: String::from("user_denied"),
                            terminal_receipt: None,
                        },
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidPluginContextOperation)
        ));
        let policy_rejected = reduce(
            Some(completed.clone()),
            &envelope(
                12,
                RuntimeCommittedEvent::PluginContextOperationFailed(Box::new(
                    PluginContextOperationFailedEvent {
                        identity: identity.clone(),
                        action_digest: Some(action_digest),
                        code: String::from("application_policy_denied"),
                        terminal_receipt: None,
                    },
                )),
            ),
        )
        .expect("direct application policy rejection");
        assert_eq!(
            policy_rejected.plugin_context_operations[&identity.invocation_id].state,
            PluginContextOperationState::Failed
        );
        let approval_id = continuation_id();
        let subject = ApprovalSubject::PluginContextOperation {
            invocation_id: identity.invocation_id.clone(),
            invocation_digest: identity.invocation_digest,
            stage: PluginContextApprovalStage::Application,
            action_digest,
            proposal_hash: Some(proposal_hash),
            replacement_hash: Some(replacement_hash),
        };
        let requested = reduce(
            Some(completed),
            &envelope(
                12,
                RuntimeCommittedEvent::ApprovalRequested(ApprovalRequestedEvent {
                    continuation_id: approval_id,
                    action_summary: String::from("apply plugin memory"),
                    subject: Some(subject),
                }),
            ),
        )
        .expect("application request");
        let denied = reduce(
            Some(requested),
            &envelope(
                13,
                RuntimeCommittedEvent::ApprovalResolved(ApprovalResolvedEvent {
                    continuation_id: approval_id,
                    approved: false,
                }),
            ),
        )
        .expect("application denial");
        let before = denied.plugin_context_operations[&identity.invocation_id].clone();
        let failed = reduce(
            Some(denied),
            &envelope(
                14,
                RuntimeCommittedEvent::PluginContextOperationFailed(Box::new(
                    PluginContextOperationFailedEvent {
                        identity: identity.clone(),
                        action_digest: Some(action_digest),
                        code: String::from("user_denied"),
                        terminal_receipt: None,
                    },
                )),
            ),
        )
        .expect("linked terminal denial");
        let after = &failed.plugin_context_operations[&identity.invocation_id];
        assert_eq!(after.state, PluginContextOperationState::Failed);
        assert_eq!(after.proposal, before.proposal);
        assert_eq!(after.terminal_receipt, before.terminal_receipt);
    }

    #[test]
    fn plugin_context_final_mandatory_denial_requires_prior_exact_application_approval() {
        let (completed, identity, proposal_hash, replacement_hash, action_digest) =
            completed_plugin_memory_operation();
        let approval_id = continuation_id();
        let subject = ApprovalSubject::PluginContextOperation {
            invocation_id: identity.invocation_id.clone(),
            invocation_digest: identity.invocation_digest,
            stage: PluginContextApprovalStage::Application,
            action_digest,
            proposal_hash: Some(proposal_hash),
            replacement_hash: Some(replacement_hash),
        };
        let requested = reduce(
            Some(completed),
            &envelope(
                12,
                RuntimeCommittedEvent::ApprovalRequested(ApprovalRequestedEvent {
                    continuation_id: approval_id,
                    action_summary: String::from("apply plugin memory"),
                    subject: Some(subject),
                }),
            ),
        )
        .expect("application request");
        let resolved = reduce(
            Some(requested),
            &envelope(
                13,
                RuntimeCommittedEvent::ApprovalResolved(ApprovalResolvedEvent {
                    continuation_id: approval_id,
                    approved: true,
                }),
            ),
        )
        .expect("application approval");
        let application_approved = reduce(
            Some(resolved),
            &envelope(
                14,
                RuntimeCommittedEvent::PluginContextOperationApplicationApproved(Box::new(
                    PluginContextOperationApplicationApprovedEvent {
                        identity: identity.clone(),
                        proposal_hash,
                        replacement_hash,
                        action_digest,
                    },
                )),
            ),
        )
        .expect("canonical application approval");
        let failed = reduce(
            Some(application_approved),
            &envelope(
                15,
                RuntimeCommittedEvent::PluginContextOperationFailed(Box::new(
                    PluginContextOperationFailedEvent {
                        identity: identity.clone(),
                        action_digest: Some(action_digest),
                        code: String::from("mandatory_policy_denied"),
                        terminal_receipt: None,
                    },
                )),
            ),
        )
        .expect("mandatory denial");
        assert_eq!(
            failed.plugin_context_operations[&identity.invocation_id].state,
            PluginContextOperationState::Failed
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the crash-prefix matrix proves every canonical plugin context cut and tamper binding"
    )]
    fn plugin_context_operation_reducer_is_exact_and_recovery_is_fail_closed() {
        let (state, phase) = plugin_memory_context_state();
        let request = plugin_memory_request();
        let readable_state = plugin_context_operation_inputs_json(
            &serde_json::json!({"session": session_id().to_string()}),
        );
        let identity = plugin_context_operation_identity(&state, phase, &request, &readable_state)
            .expect("operation identity");
        assert_eq!(
            classify_plugin_context_operation_recovery(&state, &identity.invocation_id, None),
            PluginContextOperationRecovery::NotStarted
        );
        let proposed = reduce(
            Some(state),
            &envelope(
                8,
                RuntimeCommittedEvent::PluginContextOperationProposed(Box::new(
                    PluginContextOperationProposedEvent {
                        identity: identity.clone(),
                        request,
                        readable_state,
                    },
                )),
            ),
        )
        .expect("proposed");
        assert_eq!(
            classify_plugin_context_operation_recovery(&proposed, &identity.invocation_id, None),
            PluginContextOperationRecovery::AwaitPolicy
        );
        let mut substituted = identity.clone();
        substituted.declaration_hash = ContentHash::digest(b"substituted");
        assert!(matches!(
            reduce(
                Some(proposed.clone()),
                &envelope(
                    9,
                    RuntimeCommittedEvent::PluginContextOperationAuthorized(Box::new(
                        PluginContextOperationAuthorizedEvent {
                            identity: substituted,
                            action_digest: ContentHash::digest(b"action"),
                            authorization_digest: ContentHash::digest(b"authorization"),
                        },
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidPluginContextOperation)
        ));
        let authorized = authorize_plugin_context_operation(proposed, &identity, 9);
        assert_eq!(
            classify_plugin_context_operation_recovery(&authorized, &identity.invocation_id, None),
            PluginContextOperationRecovery::SafeToDispatchOnce
        );
        let action_digest = authorized
            .plugin_context_operations
            .get(&identity.invocation_id)
            .and_then(|record| record.action_digest)
            .expect("action digest");
        let dispatched = reduce(
            Some(authorized),
            &envelope(
                10,
                RuntimeCommittedEvent::PluginContextOperationDispatched(Box::new(
                    PluginContextOperationDispatchedEvent {
                        identity: identity.clone(),
                        action_digest,
                    },
                )),
            ),
        )
        .expect("dispatched");
        assert_eq!(
            classify_plugin_context_operation_recovery(&dispatched, &identity.invocation_id, None),
            PluginContextOperationRecovery::AmbiguousFailClosed
        );
        let receipt = SealedPluginContextReceipt {
            receipt_hash: ContentHash::digest(b"terminal receipt"),
            receipt_reference: String::from("plugin-receipt:memory:1"),
        };
        let evidence = PluginContextOperationReceiptEvidence {
            invocation_id: identity.invocation_id.clone(),
            invocation_digest: identity.invocation_digest,
            terminal_receipt: receipt.clone(),
        };
        assert_eq!(
            classify_plugin_context_operation_recovery(
                &dispatched,
                &identity.invocation_id,
                Some(&evidence)
            ),
            PluginContextOperationRecovery::SafeToCompleteFromReceipt
        );
        let (retrieved, retrieved_entry_ids) =
            plugin_memory_replacement(&identity, receipt.receipt_hash, 11);
        let mut replacement = dispatched.conversation.provider_projection().to_vec();
        replacement.extend(retrieved.clone());
        let proposal = PluginContextOperationProposal::MemoryRetrieve {
            replacement: replacement.clone(),
            retrieved_entry_ids: retrieved_entry_ids.clone(),
        };
        let proposal_hash = bounded_json_hash(&proposal, MAX_PLUGIN_CONTEXT_OPERATION_BYTES)
            .expect("proposal hash");
        let invalid_proposal = PluginContextOperationProposal::MemoryRetrieve {
            replacement: retrieved,
            retrieved_entry_ids,
        };
        assert!(matches!(
            reduce(
                Some(dispatched.clone()),
                &envelope(
                    11,
                    RuntimeCommittedEvent::PluginContextOperationCompleted(Box::new(
                        PluginContextOperationCompletedEvent {
                            identity: identity.clone(),
                            proposal_hash: bounded_json_hash(
                                &invalid_proposal,
                                MAX_PLUGIN_CONTEXT_OPERATION_BYTES,
                            )
                            .expect("invalid proposal hash"),
                            proposal: invalid_proposal,
                            terminal_receipt: receipt.clone(),
                        },
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidPluginContextOperation)
        ));
        let completed = reduce(
            Some(dispatched),
            &envelope(
                11,
                RuntimeCommittedEvent::PluginContextOperationCompleted(Box::new(
                    PluginContextOperationCompletedEvent {
                        identity: identity.clone(),
                        proposal,
                        proposal_hash,
                        terminal_receipt: receipt,
                    },
                )),
            ),
        )
        .expect("completed");
        assert_eq!(
            classify_plugin_context_operation_recovery(&completed, &identity.invocation_id, None),
            PluginContextOperationRecovery::AwaitApplicationAuthorization
        );
        let replacement_hash = bounded_json_hash(&replacement, MAX_PLUGIN_CONTEXT_OPERATION_BYTES)
            .expect("replacement hash");
        let binding = completed.style_binding.as_ref().expect("binding");
        let replacement_action = context_replacement_action_proposal(
            &binding.id,
            &completed.workspace,
            &identity.phase.boundary.run_id,
            &identity.phase.phase,
            replacement_hash,
        )
        .digest()
        .expect("replacement action");
        let approved = reduce(
            Some(completed),
            &envelope(
                12,
                RuntimeCommittedEvent::PluginContextOperationApplicationApproved(Box::new(
                    PluginContextOperationApplicationApprovedEvent {
                        identity: identity.clone(),
                        proposal_hash,
                        replacement_hash,
                        action_digest: replacement_action,
                    },
                )),
            ),
        )
        .expect("application approved");
        assert_eq!(
            classify_plugin_context_operation_recovery(&approved, &identity.invocation_id, None),
            PluginContextOperationRecovery::SafeToApply
        );
        let application_hash =
            plugin_context_operation_application_hash(&identity, proposal_hash, replacement_hash);
        let applied = reduce(
            Some(approved),
            &envelope(
                13,
                RuntimeCommittedEvent::PluginContextOperationApplied(Box::new(
                    PluginContextOperationAppliedEvent {
                        identity: identity.clone(),
                        proposal_hash,
                        replacement,
                        replacement_hash,
                        application_hash,
                        provenance: ProjectionProvenance {
                            projection_id: format!(
                                "plugin-context-operation:{}:13",
                                identity.invocation_id
                            ),
                            source_range: None,
                            method: String::from("plugin_memory_retrieve"),
                            committed_at: Sequence::new(13).expect("sequence"),
                            artifact_id: None,
                        },
                    },
                )),
            ),
        )
        .expect("applied");
        assert_eq!(
            classify_plugin_context_operation_recovery(&applied, &identity.invocation_id, None),
            PluginContextOperationRecovery::Applied
        );
        assert_eq!(applied.conversation.provider_projection().len(), 2);
    }

    #[test]
    fn plugin_context_operation_serde_defaults_preserve_legacy_session_state() {
        let (state, _) = plugin_memory_context_state();
        let mut encoded = serde_json::to_value(state).expect("state JSON");
        encoded
            .as_object_mut()
            .expect("state object")
            .remove("plugin_context_operations");
        let legacy: SessionState = serde_json::from_value(encoded).expect("legacy state");
        assert!(legacy.plugin_context_operations.is_empty());
    }

    #[test]
    fn plugin_memory_identity_binds_every_retrieval_timing_exactly() {
        let (base, phase) = plugin_memory_context_state();
        let request = plugin_memory_request();
        let readable_state = plugin_context_operation_inputs_json(&serde_json::json!({}));
        for (timing, boundary) in [
            ("turn_start", "turn_start"),
            ("iteration_start", "iteration_start"),
            ("context_node", "context_node"),
            ("before_model_request", "before_model_request"),
        ] {
            let mut state = base.clone();
            state
                .style_binding
                .as_mut()
                .expect("binding")
                .memory
                .retrieval_timing = timing.to_owned();
            let mut exact_phase = phase.clone();
            exact_phase.boundary.boundary = boundary.to_owned();
            assert!(
                plugin_context_operation_identity(
                    &state,
                    exact_phase.clone(),
                    &request,
                    &readable_state,
                )
                .is_ok(),
                "{timing} must bind its exact canonical boundary"
            );
            exact_phase.boundary.boundary = String::from("turn_start");
            if timing != "turn_start" {
                assert!(matches!(
                    plugin_context_operation_identity(
                        &state,
                        exact_phase,
                        &request,
                        &readable_state,
                    ),
                    Err(SessionReducerError::InvalidPluginContextOperation)
                ));
            }
        }
    }

    #[test]
    fn plugin_compaction_preservation_requires_exact_protected_entries() {
        let sequence = Sequence::new(2).expect("sequence");
        let source = vec![
            ConversationEntry::SystemInstruction(TextEntry {
                id: ConversationEntryId(String::from("system")),
                text: String::from("immutable system policy"),
                source_sequence: sequence,
            }),
            ConversationEntry::UserMessage(TextEntry {
                id: ConversationEntryId(String::from("user-current")),
                text: String::from("current request"),
                source_sequence: sequence,
            }),
            ConversationEntry::PendingTask(crate::conversation::PendingTaskEntry {
                id: ConversationEntryId(String::from("task")),
                task_id: String::from("task-1"),
                description: String::from("pending work"),
                state: String::from("pending"),
                source_sequence: sequence,
            }),
            ConversationEntry::ActiveProcessSummary(crate::conversation::ActiveProcessEntry {
                id: ConversationEntryId(String::from("process")),
                process_id: String::from("process-1"),
                label: String::from("test runner"),
                state: String::from("running"),
                source_sequence: sequence,
            }),
        ];
        let requirements = vec![
            String::from("system_instructions"),
            String::from("current_input"),
            String::from("pending_control_state"),
        ];
        assert!(validate_plugin_compaction_preservation(&source, &source, &requirements).is_ok());
        for removed in 0..source.len() {
            let mut replacement = source.clone();
            replacement.remove(removed);
            assert!(matches!(
                validate_plugin_compaction_preservation(&source, &replacement, &requirements,),
                Err(SessionReducerError::InvalidPluginContextOperation)
            ));
        }
        let mut substituted = source.clone();
        let ConversationEntry::SystemInstruction(system) = &mut substituted[0] else {
            panic!("system fixture");
        };
        system.text = String::from("fabricated replacement");
        assert!(matches!(
            validate_plugin_compaction_preservation(&source, &substituted, &requirements),
            Err(SessionReducerError::InvalidPluginContextOperation)
        ));
    }

    fn context_transform_selection(
        plugin_id: &str,
        transform_id: &str,
        version: &str,
        declaration: &[u8],
        configuration: &[u8],
    ) -> ContextTransformSelection {
        ContextTransformSelection {
            plugin_id: plugin_id.into(),
            transform_id: transform_id.into(),
            version: version.into(),
            declaration_hash: ContentHash::digest(declaration),
            lifecycle: ContextTransformLifecycle::BeforeModelRequest,
            configuration_reference: ContentHash::digest(configuration),
        }
    }

    fn dynamic_context_style_binding(
        selections: &[ContextTransformSelection],
    ) -> SessionStyleBinding {
        let mut style_binding = binding(BuiltInStyle::PersistentChat);
        let mut compiled: CompiledSessionStyle =
            serde_json::from_str(&style_binding.compiled_style_json).expect("compiled style");
        compiled.context_transforms = selections.to_vec();
        style_binding.compiled_style_json =
            serde_json::to_string(&compiled).expect("compiled style JSON");
        style_binding.execution_plan = None;
        style_binding.execution_plan_hash = None;
        style_binding
    }

    fn context_phase(boundary: &ContextBoundaryIdentity, phase: &str) -> ContextPhaseIdentity {
        ContextPhaseIdentity {
            boundary: boundary.clone(),
            phase: phase.into(),
        }
    }

    fn dynamic_context_transform_state() -> (
        SessionState,
        ContextBoundaryIdentity,
        Vec<ContextTransformSelection>,
    ) {
        let selections = vec![
            context_transform_selection(
                "fixture.redactor",
                "fixture.redact",
                "1.2.3",
                b"redact declaration",
                b"redact configuration",
            ),
            context_transform_selection(
                "fixture.annotator",
                "fixture.annotate",
                "2.0.0",
                b"annotate declaration",
                b"annotate configuration",
            ),
        ];
        let style_binding = dynamic_context_style_binding(&selections);

        let turn = context_identity("turn_start", 3, ContextBoundaryOrigin::UserTurn);
        let turn_phase = context_phase(&turn, "memory");
        let empty = measure_projection(&[]).expect("empty measurement");
        let before = context_identity("before_model_request", 7, ContextBoundaryOrigin::UserTurn);
        let before_memory = context_phase(&before, "memory");
        let state = replay(&[
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: style_binding.id.clone(),
                    style_binding: Some(Box::new(style_binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(context_graph()),
                        input_reference: None,
                        execution_contract: None,
                    },
                )),
            ),
            envelope(
                3,
                RuntimeCommittedEvent::StyleNodeEntered(StyleNodeEnteredEvent {
                    node_id: String::from("respond"),
                    attempt: 1,
                    loop_iteration: 0,
                    step: 1,
                }),
            ),
            envelope(
                4,
                RuntimeCommittedEvent::ContextBoundaryStarted(ContextBoundaryStartedEvent {
                    identity: turn.clone(),
                }),
            ),
            envelope(
                5,
                RuntimeCommittedEvent::ContextPhaseStarted(ContextPhaseStartedEvent {
                    identity: turn_phase.clone(),
                }),
            ),
            envelope(
                6,
                RuntimeCommittedEvent::ContextPhaseCompleted(ContextPhaseCompletedEvent {
                    identity: turn_phase,
                }),
            ),
            envelope(
                7,
                RuntimeCommittedEvent::ContextBoundaryCompleted(ContextBoundaryCompletedEvent {
                    identity: turn,
                    projection_hash: empty.projection_hash,
                    estimated_tokens: empty.estimated_tokens,
                    serialized_bytes: empty.serialized_bytes,
                }),
            ),
            envelope(
                8,
                RuntimeCommittedEvent::ContextBoundaryStarted(ContextBoundaryStartedEvent {
                    identity: before.clone(),
                }),
            ),
            envelope(
                9,
                RuntimeCommittedEvent::ContextPhaseStarted(ContextPhaseStartedEvent {
                    identity: before_memory.clone(),
                }),
            ),
            envelope(
                10,
                RuntimeCommittedEvent::ContextPhaseCompleted(ContextPhaseCompletedEvent {
                    identity: before_memory,
                }),
            ),
        ])
        .expect("dynamic context-transform state");
        (state, before, selections)
    }

    fn plugin_context_identity(
        state: &SessionState,
        phase: ContextPhaseIdentity,
        ordinal: u32,
        selection: &ContextTransformSelection,
    ) -> PluginContextTransformIdentity {
        let input =
            plugin_context_transform_input(state, &phase, ordinal).expect("transform input");
        let input_hash = serde_json::to_vec(&input)
            .map(|bytes| ContentHash::digest(&bytes))
            .expect("transform input JSON");
        plugin_context_transform_identity(
            phase,
            ordinal,
            selection,
            input_hash,
            ContentHash::digest(b"{}"),
        )
        .expect("transform identity")
    }

    fn dispatch_completed_plugin_context_transform(
        mut state: SessionState,
        boundary: &ContextBoundaryIdentity,
        ordinal: u32,
        selection: &ContextTransformSelection,
        first_sequence: u64,
    ) -> (
        SessionState,
        ContextPhaseIdentity,
        PluginContextTransformIdentity,
        Vec<ConversationEntry>,
        ContentHash,
    ) {
        let phase = ContextPhaseIdentity {
            boundary: boundary.clone(),
            phase: format!("plugin_context_transform:{ordinal}"),
        };
        state = reduce(
            Some(state),
            &envelope(
                first_sequence,
                RuntimeCommittedEvent::ContextPhaseStarted(ContextPhaseStartedEvent {
                    identity: phase.clone(),
                }),
            ),
        )
        .expect("plugin phase start");
        let identity = plugin_context_identity(&state, phase.clone(), ordinal, selection);
        state = reduce(
            Some(state),
            &envelope(
                first_sequence + 1,
                RuntimeCommittedEvent::PluginContextTransformProposed(Box::new(
                    PluginContextTransformProposedEvent {
                        identity: identity.clone(),
                    },
                )),
            ),
        )
        .expect("plugin transform proposal");
        state = reduce(
            Some(state),
            &envelope(
                first_sequence + 2,
                RuntimeCommittedEvent::PluginContextTransformDispatched(Box::new(
                    PluginContextTransformDispatchedEvent {
                        identity: identity.clone(),
                    },
                )),
            ),
        )
        .expect("plugin transform dispatch");
        let replacement = Vec::new();
        let replacement_hash = serde_json::to_vec(&replacement)
            .map(|bytes| ContentHash::digest(&bytes))
            .expect("replacement JSON");
        state = reduce(
            Some(state),
            &envelope(
                first_sequence + 3,
                RuntimeCommittedEvent::PluginContextTransformCompleted(Box::new(
                    PluginContextTransformCompletedEvent {
                        identity: identity.clone(),
                        replacement: replacement.clone(),
                        replacement_hash,
                        attempts: 1,
                        terminal_receipt_hash: ContentHash::digest(b"terminal receipt"),
                    },
                )),
            ),
        )
        .expect("plugin transform completion");
        (state, phase, identity, replacement, replacement_hash)
    }

    fn apply_successful_plugin_context_transform(
        state: SessionState,
        boundary: &ContextBoundaryIdentity,
        ordinal: u32,
        selection: &ContextTransformSelection,
        first_sequence: u64,
    ) -> SessionState {
        let (mut state, phase, identity, replacement, replacement_hash) =
            dispatch_completed_plugin_context_transform(
                state,
                boundary,
                ordinal,
                selection,
                first_sequence,
            );
        let style = state.style_binding.as_ref().expect("style binding");
        let action_digest = context_replacement_action_proposal(
            &style.id,
            &state.workspace,
            &boundary.run_id,
            &phase.phase,
            replacement_hash,
        )
        .digest()
        .expect("replacement action digest");
        state = reduce(
            Some(state),
            &envelope(
                first_sequence + 4,
                RuntimeCommittedEvent::PluginContextTransformReplacementApproved(Box::new(
                    PluginContextTransformReplacementApprovedEvent {
                        identity: identity.clone(),
                        replacement_hash,
                        action_digest,
                    },
                )),
            ),
        )
        .expect("plugin replacement approval");
        let replacement_sequence = Sequence::new(first_sequence + 5).expect("replacement sequence");
        reduce(
            Some(state),
            &envelope(
                first_sequence + 5,
                RuntimeCommittedEvent::ContextProjectionReplaced(ContextProjectionReplacedEvent {
                    replacement,
                    provenance: ProjectionProvenance {
                        projection_id: format!(
                            "plugin-context-transform:{}:{}",
                            identity.invocation_id,
                            replacement_sequence.get()
                        ),
                        source_range: None,
                        method: String::from("plugin_context_transform"),
                        committed_at: replacement_sequence,
                        artifact_id: None,
                    },
                    context_phase: Some(phase),
                }),
            ),
        )
        .expect("plugin replacement application")
    }

    #[test]
    fn dynamic_context_phases_reject_wrong_order_and_substituted_transform_identity() {
        let (state, boundary, selections) = dynamic_context_transform_state();
        let second_phase = ContextPhaseIdentity {
            boundary: boundary.clone(),
            phase: String::from("plugin_context_transform:1"),
        };
        assert!(matches!(
            reduce(
                Some(state.clone()),
                &envelope(
                    11,
                    RuntimeCommittedEvent::ContextPhaseStarted(ContextPhaseStartedEvent {
                        identity: second_phase,
                    }),
                ),
            ),
            Err(SessionReducerError::InvalidContextBoundaryTransition)
        ));

        let first_phase = ContextPhaseIdentity {
            boundary,
            phase: String::from("plugin_context_transform:0"),
        };
        let started = reduce(
            Some(state),
            &envelope(
                11,
                RuntimeCommittedEvent::ContextPhaseStarted(ContextPhaseStartedEvent {
                    identity: first_phase.clone(),
                }),
            ),
        )
        .expect("first plugin phase");
        let identity = plugin_context_identity(&started, first_phase, 0, &selections[0]);

        let mut substituted_ordinal = identity.clone();
        substituted_ordinal.ordinal = 1;
        assert!(matches!(
            reduce(
                Some(started.clone()),
                &envelope(
                    12,
                    RuntimeCommittedEvent::PluginContextTransformProposed(Box::new(
                        PluginContextTransformProposedEvent {
                            identity: substituted_ordinal,
                        }
                    ),),
                ),
            ),
            Err(SessionReducerError::InvalidPluginContextTransform)
        ));

        let mut substituted_hash = identity;
        substituted_hash.declaration_hash = ContentHash::digest(b"substituted declaration");
        assert!(matches!(
            reduce(
                Some(started),
                &envelope(
                    12,
                    RuntimeCommittedEvent::PluginContextTransformProposed(Box::new(
                        PluginContextTransformProposedEvent {
                            identity: substituted_hash,
                        }
                    ),),
                ),
            ),
            Err(SessionReducerError::InvalidPluginContextTransform)
        ));
    }

    #[test]
    fn dynamic_context_phases_complete_two_immutable_transforms_before_compaction() {
        let (state, boundary, selections) = dynamic_context_transform_state();
        let state =
            apply_successful_plugin_context_transform(state, &boundary, 0, &selections[0], 11);
        let state =
            apply_successful_plugin_context_transform(state, &boundary, 1, &selections[1], 17);
        let compaction = ContextPhaseIdentity {
            boundary: boundary.clone(),
            phase: String::from("compaction"),
        };
        let state = reduce(
            Some(state),
            &envelope(
                23,
                RuntimeCommittedEvent::ContextPhaseStarted(ContextPhaseStartedEvent {
                    identity: compaction.clone(),
                }),
            ),
        )
        .expect("compaction phase start");
        let state = reduce(
            Some(state),
            &envelope(
                24,
                RuntimeCommittedEvent::ContextPhaseCompleted(ContextPhaseCompletedEvent {
                    identity: compaction,
                }),
            ),
        )
        .expect("compaction phase completion");
        let measurement = measure_projection(&[]).expect("empty measurement");
        let state = reduce(
            Some(state),
            &envelope(
                25,
                RuntimeCommittedEvent::ContextBoundaryCompleted(ContextBoundaryCompletedEvent {
                    identity: boundary,
                    projection_hash: measurement.projection_hash,
                    estimated_tokens: measurement.estimated_tokens,
                    serialized_bytes: measurement.serialized_bytes,
                }),
            ),
        )
        .expect("dynamic context boundary completion");

        let execution = state.style_execution.expect("style execution");
        let completed = execution
            .context_boundaries
            .last()
            .expect("context boundary");
        assert_eq!(
            completed.completed_phases,
            [
                "memory",
                "plugin_context_transform:0",
                "plugin_context_transform:1",
                "compaction",
            ]
        );
        assert_eq!(
            completed.completed_at,
            Some(Sequence::new(25).expect("sequence"))
        );
        assert_eq!(state.plugin_context_transforms.len(), 2);
        assert!(state.plugin_context_transforms.values().all(|record| {
            record.state == PluginContextTransformState::Applied
                && record.applied_event_id.is_some()
        }));
    }

