    #[test]
    fn tool_dispatch_outbox_replays_to_a_terminal_state() {
        let digest = ContentHash::digest(b"approved tool action");
        let events = vec![
            created(),
            envelope(
                2,
                RuntimeCommittedEvent::ToolExecutionDispatched(ToolExecutionDispatchedEvent {
                    execution_id: "execution-1".into(),
                    call_id: "call-1".into(),
                    action_digest: digest,
                }),
            ),
            envelope(
                3,
                RuntimeCommittedEvent::ToolExecutionStarted(ToolExecutionStartedEvent {
                    call_id: "call-1".into(),
                }),
            ),
            envelope(
                4,
                RuntimeCommittedEvent::ToolExecutionCompleted(ToolExecutionCompletedEvent {
                    call_id: "call-1".into(),
                    result: serde_json::json!({"ok":true}),
                    artifact: None,
                    truncated: false,
                }),
            ),
        ];

        let state = replay(&events).expect("replay");
        let execution = &state.tool_executions["call-1"];
        assert_eq!(execution.execution_id.as_deref(), Some("execution-1"));
        assert_eq!(execution.action_digest, Some(digest));
        assert_eq!(execution.state, ToolExecutionState::Terminal);
        assert_eq!(execution.observed_event_count, 2);
        assert_eq!(
            execution.terminal_at,
            Some(Sequence::new(4).expect("sequence"))
        );
        assert!(matches!(
            execution.terminal_outcome,
            Some(ToolExecutionTerminalOutcome::Completed { .. })
        ));
    }

    fn generic_effect_evidence_graph(kind: NodeKind) -> ExecutableGraph {
        let (entry, node) = match kind {
            NodeKind::ContextTransform => (
                "construct-context",
                r#"
[[nodes]]
id = "construct-context"
kind = "context_transform"
configuration = { type = "context_transform", strategy = "preserve_history" }
"#,
            ),
            NodeKind::ModelCall => (
                "invoke-model",
                r#"
[[nodes]]
id = "invoke-model"
kind = "model_call"
provider = "fixture"
"#,
            ),
            NodeKind::UserApproval => (
                "authorize-change",
                r#"
[[nodes]]
id = "authorize-change"
kind = "user_approval"
configuration = { type = "user_approval", action_summary = { kind = "static", value = "approve generic change" } }
"#,
            ),
            NodeKind::ToolExecutionGate => (
                "inspect-workspace",
                r#"
[[nodes]]
id = "inspect-workspace"
kind = "tool_execution_gate"
tool = "filesystem.read"
configuration = { type = "tool_execution", arguments = { kind = "static", value = { path = "README.md" } } }
"#,
            ),
            _ => panic!("unsupported effect-evidence fixture"),
        };
        compile_graph(
            &format!(
                r#"
format_version = 1
entry = "{entry}"
[budget]
max_steps = 8
max_tokens = 100
max_cost_micros = 100
max_duration_ms = 10000
[declarations]
capabilities = ["approval", "context", "model", "tools"]
tools = ["filesystem.read"]
providers = ["fixture"]
{node}
[[nodes]]
id = "finish-generic"
kind = "complete_session"

[[edges]]
from = "{entry}"
to = "finish-generic"
"#
            ),
            &GraphCacheInputs {
                plugin_set_hash: ContentHash::digest(b"generic-effect-evidence-plugins"),
                runtime_api_version: String::from("0.1.0"),
                capability_set: BTreeSet::from([
                    String::from("approval"),
                    String::from("context"),
                    String::from("model"),
                    String::from("tools"),
                ]),
            },
            CompilerLimits::default(),
        )
        .expect("generic effect-evidence graph")
    }

    fn generic_effect_evidence_binding(graph: &ExecutableGraph) -> SessionStyleBinding {
        let mut result = binding(BuiltInStyle::PersistentChat);
        let mut compiled: CompiledSessionStyle =
            serde_json::from_str(&result.compiled_style_json).expect("compiled fixture");
        compiled.style_id = String::from("inline-effect-evidence@1.0.0");
        compiled.graph = graph.clone();
        result.id = compiled.style_id.clone();
        result.source = SessionStyleSource::Inline;
        result.source_locator = String::from("inline:effect-evidence");
        result.compiled_style_json = serde_json::to_string(&compiled).expect("compiled graph");
        result.compiled_style_hash = ContentHash::digest(result.compiled_style_json.as_bytes());
        result.execution_plan = None;
        result.execution_plan_hash = None;
        crate::node_executor::bind_runtime_execution_plan(
            &agentmod_runtime_data::node_executor::RuntimeNodeExecutorData::native()
                .expect("native registry"),
            &mut result,
        )
        .expect("generic execution plan");
        result
    }

    fn active_generic_effect_state(kind: NodeKind) -> SessionState {
        let graph = generic_effect_evidence_graph(kind);
        let binding = generic_effect_evidence_binding(&graph);
        let contract = test_execution_contract(&binding, &graph);
        let entry = graph.nodes[graph.entry_index].id.clone();
        replay(&[
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(graph),
                        input_reference: None,
                        execution_contract: Some(Box::new(contract)),
                    },
                )),
            ),
            style_entered(3, &entry, 1),
        ])
        .expect("active generic effect")
    }

