    #[test]
    fn generic_approval_completion_requires_exact_executor_bound_continuation() {
        let state = active_generic_effect_state(NodeKind::UserApproval);
        let completed = StyleNodeCompletedEvent {
            node_id: String::from("authorize-change"),
            attempt: 1,
            loop_iteration: 0,
            step: 1,
            result_reference: None,
            artifact_reference: None,
        };
        assert!(matches!(
            reduce(
                Some(state.clone()),
                &envelope(
                    4,
                    RuntimeCommittedEvent::StyleNodeCompleted(completed.clone())
                )
            ),
            Err(SessionReducerError::InvalidStyleExecutionTransition)
        ));

        let execution = state.style_execution.as_ref().expect("execution");
        let (resolution, NativeExecutorKey::UserApproval) =
            resolved_native_executor(execution, &completed.node_id).expect("approval executor")
        else {
            panic!("approval executor");
        };
        let exact =
            generic_approval_continuation_id(execution, &completed, resolution).expect("identity");
        let unrelated =
            ContinuationId::from_uuid(Uuid::from_u128(exact.into_uuid().as_u128().wrapping_add(1)));
        let unrelated_state = reduce(
            Some(state.clone()),
            &envelope(
                4,
                RuntimeCommittedEvent::ApprovalRequested(ApprovalRequestedEvent {
                    continuation_id: unrelated,
                    action_summary: String::from("unrelated approval"),
                    subject: None,
                }),
            ),
        )
        .and_then(|state| {
            reduce(
                Some(state),
                &envelope(
                    5,
                    RuntimeCommittedEvent::ApprovalResolved(ApprovalResolvedEvent {
                        continuation_id: unrelated,
                        approved: true,
                    }),
                ),
            )
        })
        .expect("unrelated approval");
        let mut claimed = completed.clone();
        claimed.result_reference = Some(format!("generic-approval:{unrelated}"));
        assert!(matches!(
            reduce(
                Some(unrelated_state),
                &envelope(6, RuntimeCommittedEvent::StyleNodeCompleted(claimed))
            ),
            Err(SessionReducerError::InvalidStyleExecutionTransition)
        ));

        let exact_state = reduce(
            Some(state),
            &envelope(
                4,
                RuntimeCommittedEvent::ApprovalRequested(ApprovalRequestedEvent {
                    continuation_id: exact,
                    action_summary: String::from("approve generic change"),
                    subject: None,
                }),
            ),
        )
        .and_then(|state| {
            reduce(
                Some(state),
                &envelope(
                    5,
                    RuntimeCommittedEvent::ApprovalResolved(ApprovalResolvedEvent {
                        continuation_id: exact,
                        approved: true,
                    }),
                ),
            )
        })
        .expect("exact approval");
        let mut completed = completed;
        completed.result_reference = Some(format!("generic-approval:{exact}"));
        reduce(
            Some(exact_state),
            &envelope(6, RuntimeCommittedEvent::StyleNodeCompleted(completed)),
        )
        .expect("exact approval receipt authorizes completion");
    }

