    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the regression keeps the complete adapter-shaped V3 graph next to its replay assertion"
    )]
    fn generic_completion_does_not_require_a_legacy_topology_receipt() {
        let graph = compile_graph(
            r#"
format_version = 1
entry = "prepare-context"
[budget]
max_steps = 8
max_tokens = 100
max_cost_micros = 100
max_duration_ms = 10000
[declarations]
capabilities = ["context", "model", "tools"]
tools = ["filesystem.read"]
providers = ["fixture"]
[[nodes]]
id = "prepare-context"
kind = "context_transform"
configuration = { type = "context_transform", strategy = "fresh" }
[[nodes]]
id = "respond"
kind = "model_call"
provider = "fixture"
[[nodes]]
id = "tool"
kind = "tool_execution_gate"
tool = "filesystem.read"
configuration = { type = "tool_execution", arguments = { kind = "static", value = {} } }
[[nodes]]
id = "done"
kind = "complete_turn"
[[edges]]
from = "prepare-context"
to = "respond"
[[edges]]
from = "respond"
to = "tool"
[[edges]]
from = "tool"
to = "done"
"#,
            &GraphCacheInputs {
                plugin_set_hash: ContentHash::digest(b"generic-topology-plugins"),
                runtime_api_version: String::from("0.1.0"),
                capability_set: BTreeSet::from([
                    String::from("context"),
                    String::from("model"),
                    String::from("tools"),
                ]),
            },
            CompilerLimits::default(),
        )
        .expect("generic adapter-shaped graph");
        assert!(is_ephemeral_turn_graph(&graph));
        let binding = generic_effect_evidence_binding(&graph);
        let contract = test_execution_contract(&binding, &graph);
        let mut state = replay(&[
            envelope(
                1,
                RuntimeCommittedEvent::SessionCreated(SessionCreatedEvent {
                    workspace: String::from("fixture"),
                    style: binding.id.clone(),
                    style_binding: Some(Box::new(binding)),
                }),
            ),
            envelope(
                2,
                RuntimeCommittedEvent::StyleExecutionInitialized(Box::new(
                    StyleExecutionInitializedEvent {
                        graph: Box::new(graph),
                        input_reference: None,
                        execution_contract: Some(Box::new(contract)),
                    },
                )),
            ),
            style_entered(3, "prepare-context", 1),
        ])
        .expect("generic execution state");
        let terminal = StyleNodeEnteredEvent {
            node_id: String::from("done"),
            attempt: 1,
            loop_iteration: 0,
            step: 4,
        };
        let execution = state.style_execution.as_mut().expect("execution");
        execution.active_node = Some(terminal.clone());
        execution.active_node_entered_at = Some(Sequence::new(3).expect("sequence"));
        execution.control = StyleExecutionControlState::Active(terminal);

        reduce(
            Some(state),
            &envelope(
                4,
                RuntimeCommittedEvent::StyleNodeCompleted(StyleNodeCompletedEvent {
                    node_id: String::from("done"),
                    attempt: 1,
                    loop_iteration: 0,
                    step: 4,
                    result_reference: Some(String::from("generic:CompleteTurn")),
                    artifact_reference: None,
                }),
            ),
        )
        .expect("generic completion ignores the legacy topology classifier");
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the binding matrix keeps exact duplicate, substitution, and completion-evidence invariants adjacent"
    )]
    fn generic_provider_tool_batch_binding_is_idempotent_and_substitution_resistant() {
        let mut state = active_generic_effect_state(NodeKind::ToolExecutionGate);
        let (work, executor) = {
            let execution = state.style_execution.as_mut().expect("execution");
            let active = execution.active_node.as_ref().expect("active batch");
            let contract = execution
                .execution_contract
                .as_deref()
                .expect("execution contract");
            let executor = contract
                .node_executors
                .iter()
                .find(|resolution| resolution.node_id == active.node_id)
                .expect("batch executor")
                .clone();
            execution
                .graph
                .nodes
                .iter_mut()
                .find(|node| node.id == active.node_id)
                .expect("batch node")
                .configuration = Some(NodeConfiguration::ProviderToolBatchExecution {
                request_reference_variable: String::from("model_result"),
                disposition_variable: String::from("model_disposition"),
                maximum_calls: 4,
                allowed_tools: BTreeSet::from([String::from("filesystem.read")]),
            });
            (
                NodeWorkIdentity {
                    run_id: contract.run_id.clone(),
                    node_id: active.node_id.clone(),
                    branch_path: Vec::new(),
                    attempt: active.attempt,
                    loop_iteration: active.loop_iteration,
                    step: active.step,
                },
                executor,
            )
        };
        let model_executor = {
            let mut resolution = executor.clone();
            resolution.node_id = String::from("upstream-model");
            resolution.node_kind = String::from("model_call");
            resolution.executor_id = String::from("runtime.model-request");
            resolution
        };
        let model_phase =
            |text: &str, started_at: u64, completed_at: u64| GenericModelPhaseEvidence {
                started_at: Sequence::new(started_at).expect("start"),
                completed_at: Some(Sequence::new(completed_at).expect("completion")),
                visible_text: text.to_owned(),
                proposals: Vec::new(),
                terminal_failure: None,
            };
        let first_invocation = String::from("bound-model");
        let second_invocation = String::from("substitute-model");
        let first_phase = model_phase("first", 1, 2);
        let second_phase = model_phase("second", 1, 2);
        let first_reference =
            generic_model_result_reference(&first_invocation, &first_phase).expect("first result");
        let second_reference = generic_model_result_reference(&second_invocation, &second_phase)
            .expect("second result");
        {
            let execution = state.style_execution.as_mut().expect("execution");
            for (invocation_id, phase) in [
                (first_invocation.clone(), first_phase),
                (second_invocation.clone(), second_phase),
            ] {
                execution.generic_model_invocations.insert(
                    invocation_id.clone(),
                    GenericModelInvocationBinding {
                        binding: GenericModelInvocationBoundEvent {
                            cancellation_id: invocation_id,
                            work: NodeWorkIdentity {
                                run_id: work.run_id.clone(),
                                node_id: String::from("upstream-model"),
                                branch_path: Vec::new(),
                                attempt: 1,
                                loop_iteration: 0,
                                step: 1,
                            },
                            executor: model_executor.clone(),
                        },
                        bound_at: Sequence::new(1).expect("bound"),
                        phases: vec![phase],
                        provider_tool_batches: BTreeMap::new(),
                    },
                );
            }
        }
        let binding = GenericProviderToolBatchBoundEvent {
            work: work.clone(),
            executor: executor.clone(),
            configuration_reference: executor.adapter_configuration_reference,
            input_provider_result_reference: first_reference.clone(),
        };
        let completion = StyleNodeCompletedEvent {
            node_id: work.node_id.clone(),
            attempt: work.attempt,
            loop_iteration: work.loop_iteration,
            step: work.step,
            result_reference: Some(first_reference),
            artifact_reference: None,
        };
        assert!(matches!(
            reduce(
                Some(state.clone()),
                &envelope(
                    4,
                    RuntimeCommittedEvent::StyleNodeCompleted(completion.clone())
                )
            ),
            Err(SessionReducerError::InvalidStyleExecutionTransition)
        ));

        let bound = reduce(
            Some(state),
            &envelope(
                4,
                RuntimeCommittedEvent::GenericProviderToolBatchBound(Box::new(binding.clone())),
            ),
        )
        .expect("bind exact provider-tool input");
        let duplicate = reduce(
            Some(bound.clone()),
            &envelope(
                5,
                RuntimeCommittedEvent::GenericProviderToolBatchBound(Box::new(binding.clone())),
            ),
        )
        .expect("exact duplicate binding is idempotent");
        let replay_binding = duplicate
            .style_execution
            .as_ref()
            .expect("execution")
            .generic_model_invocations
            .get(&first_invocation)
            .expect("bound model")
            .provider_tool_batches
            .values()
            .next()
            .expect("replayed batch binding");
        assert_eq!(replay_binding.bound_at, Sequence::new(4).expect("sequence"));
        assert_eq!(replay_binding.binding, binding);

        let mut substituted = binding.clone();
        substituted
            .input_provider_result_reference
            .clone_from(&second_reference);
        assert!(matches!(
            reduce(
                Some(bound.clone()),
                &envelope(
                    5,
                    RuntimeCommittedEvent::GenericProviderToolBatchBound(Box::new(substituted)),
                )
            ),
            Err(SessionReducerError::InvalidGenericProviderToolBatch)
        ));
        let mut substituted_executor = binding.clone();
        substituted_executor.executor.executor_version = String::from("9.9.9");
        assert!(matches!(
            reduce(
                Some(bound),
                &envelope(
                    5,
                    RuntimeCommittedEvent::GenericProviderToolBatchBound(Box::new(
                        substituted_executor
                    )),
                )
            ),
            Err(SessionReducerError::InvalidGenericProviderToolBatch)
        ));
        reduce(
            Some(duplicate),
            &envelope(6, RuntimeCommittedEvent::StyleNodeCompleted(completion)),
        )
        .expect("exact bound empty batch authorizes completion");
    }

    #[test]
    fn legacy_model_tool_suspension_closes_phase_and_allows_exact_continuation() {
        let state = active_generic_effect_state(NodeKind::ModelCall);
        let cancellation_id = String::from("legacy-model-tool-loop");
        let started = reduce(
            Some(state),
            &envelope(
                4,
                RuntimeCommittedEvent::ModelRequestStarted(ModelRequestStartedEvent {
                    cancellation_id: cancellation_id.clone(),
                }),
            ),
        )
        .expect("start legacy provider phase");
        let proposal = ModelToolCallProposedEvent {
            cancellation_id: None,
            continuation_id: String::from("legacy-continuation"),
            call_id: String::from("legacy-call"),
            tool: String::from("filesystem.read"),
            arguments: serde_json::json!({"path": "README.md"}),
        };
        let proposed = reduce(
            Some(started),
            &envelope(
                5,
                RuntimeCommittedEvent::ModelToolCallProposed(proposal.clone()),
            ),
        )
        .expect("record legacy tool proposal");
        let suspension = GenericModelToolBatchSuspendedEvent {
            cancellation_id: cancellation_id.clone(),
            phase_started_at: Sequence::new(4).expect("phase start"),
            proposal_count: 1,
            proposals_hash: generic_model_tool_batch_proposals_hash(
                &cancellation_id,
                std::slice::from_ref(&proposal),
            )
            .expect("proposal hash"),
            visible_text_hash: ContentHash::digest(b""),
        };
        let mut substituted = suspension.clone();
        substituted.proposals_hash = ContentHash::digest(b"another proposal");
        assert!(matches!(
            reduce(
                Some(proposed.clone()),
                &envelope(
                    6,
                    RuntimeCommittedEvent::GenericModelToolBatchSuspended(substituted),
                ),
            ),
            Err(SessionReducerError::InvalidModelExecutionEvidence)
        ));
        let suspended = reduce(
            Some(proposed),
            &envelope(
                6,
                RuntimeCommittedEvent::GenericModelToolBatchSuspended(suspension),
            ),
        )
        .expect("suspend exact legacy tool batch");
        let evidence = suspended
            .style_execution
            .as_ref()
            .expect("execution")
            .latest_model_execution
            .as_ref()
            .expect("model evidence");
        assert_eq!(
            evidence.completed_at,
            Some(Sequence::new(6).expect("suspension sequence"))
        );
        reduce(
            Some(suspended),
            &envelope(
                7,
                RuntimeCommittedEvent::ModelRequestStarted(ModelRequestStartedEvent {
                    cancellation_id,
                }),
            ),
        )
        .expect("continue exact legacy model after canonical suspension");
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the strict model FSM matrix keeps all previously silent acceptance paths adjacent"
    )]
    fn generic_model_fsm_retains_sibling_batch_and_rejects_identity_or_terminal_reentry() {
        let state = active_generic_effect_state(NodeKind::ModelCall);
        let (run_id, node_id, attempt, loop_iteration, step, executor) = {
            let execution = state.style_execution.as_ref().expect("execution");
            let contract = execution
                .execution_contract
                .as_deref()
                .expect("execution contract");
            let active = execution.active_node.as_ref().expect("active model");
            let executor = contract
                .node_executors
                .iter()
                .find(|resolution| resolution.node_id == active.node_id)
                .expect("model executor")
                .clone();
            (
                contract.run_id.clone(),
                active.node_id.clone(),
                active.attempt,
                active.loop_iteration,
                active.step,
                executor,
            )
        };
        let cancellation_id = String::from("generic-model-phase-1");
        let proposal = |id: &str, call_id: &str| ModelToolCallProposedEvent {
            cancellation_id: Some(id.to_owned()),
            continuation_id: String::from("continuation-1"),
            call_id: call_id.to_owned(),
            tool: String::from("filesystem.read"),
            arguments: serde_json::json!({"path": format!("{call_id}.txt")}),
        };
        let bound = reduce(
            Some(state),
            &envelope(
                4,
                RuntimeCommittedEvent::GenericModelInvocationBound(Box::new(
                    GenericModelInvocationBoundEvent {
                        cancellation_id: cancellation_id.clone(),
                        work: NodeWorkIdentity {
                            run_id,
                            node_id,
                            branch_path: Vec::new(),
                            attempt,
                            loop_iteration,
                            step,
                        },
                        executor,
                    },
                )),
            ),
        )
        .expect("bind exact model invocation");
        for event in [
            RuntimeCommittedEvent::ModelToolCallProposed(proposal(
                &cancellation_id,
                "call-before-start",
            )),
            RuntimeCommittedEvent::ModelToolCallProposed(proposal("unknown-model", "call-unknown")),
            RuntimeCommittedEvent::ModelResponseCompleted(ModelResponseCompletedEvent {
                cancellation_id: cancellation_id.clone(),
                finish_reason: String::from("stop"),
                input_tokens: 1,
                output_tokens: 1,
                reasoning_tokens: 0,
                estimated: false,
                cost_micros: 0,
            }),
        ] {
            assert!(matches!(
                reduce(Some(bound.clone()), &envelope(5, event)),
                Err(SessionReducerError::InvalidModelExecutionEvidence)
            ));
        }
        let started = reduce(
            Some(bound),
            &envelope(
                5,
                RuntimeCommittedEvent::ModelRequestStarted(ModelRequestStartedEvent {
                    cancellation_id: cancellation_id.clone(),
                }),
            ),
        )
        .expect("start exact phase");
        let with_text = reduce(
            Some(started.clone()),
            &envelope(
                6,
                RuntimeCommittedEvent::ModelOutputDeltaObserved(ModelOutputDeltaObservedEvent {
                    cancellation_id: cancellation_id.clone(),
                    text: String::from("bounded"),
                }),
            ),
        )
        .expect("append exact phase text");
        assert!(matches!(
            reduce(
                Some(with_text.clone()),
                &envelope(
                    7,
                    RuntimeCommittedEvent::ModelToolCallProposed(proposal(
                        "substituted-model",
                        "call-wrong",
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidModelExecutionEvidence)
        ));
        let first = reduce(
            Some(with_text.clone()),
            &envelope(
                7,
                RuntimeCommittedEvent::ModelToolCallProposed(proposal(&cancellation_id, "call-1")),
            ),
        )
        .expect("first sibling");
        let siblings = reduce(
            Some(first),
            &envelope(
                8,
                RuntimeCommittedEvent::ModelToolCallProposed(proposal(&cancellation_id, "call-2")),
            ),
        )
        .expect("second sibling");
        let proposals = siblings
            .style_execution
            .as_ref()
            .expect("execution")
            .generic_model_invocations
            .get(&cancellation_id)
            .expect("binding")
            .phases
            .last()
            .expect("phase")
            .proposals
            .clone();
        let suspension = GenericModelToolBatchSuspendedEvent {
            cancellation_id: cancellation_id.clone(),
            phase_started_at: Sequence::new(5).expect("phase start"),
            proposal_count: 2,
            proposals_hash: generic_model_tool_batch_proposals_hash(&cancellation_id, &proposals)
                .expect("proposal hash"),
            visible_text_hash: ContentHash::digest(b"bounded"),
        };
        let mut substituted_suspension = suspension.clone();
        substituted_suspension.proposals_hash = ContentHash::digest(b"substituted batch");
        assert!(matches!(
            reduce(
                Some(siblings.clone()),
                &envelope(
                    9,
                    RuntimeCommittedEvent::GenericModelToolBatchSuspended(substituted_suspension,),
                ),
            ),
            Err(SessionReducerError::InvalidModelExecutionEvidence)
        ));
        let suspended = reduce(
            Some(siblings.clone()),
            &envelope(
                9,
                RuntimeCommittedEvent::GenericModelToolBatchSuspended(suspension),
            ),
        )
        .expect("suspend exact sibling batch");
        let suspended_phase = suspended
            .style_execution
            .as_ref()
            .expect("execution")
            .generic_model_invocations
            .get(&cancellation_id)
            .expect("binding")
            .phases
            .last()
            .expect("phase");
        assert_eq!(
            suspended_phase.completed_at,
            Some(Sequence::new(9).expect("suspension sequence"))
        );
        let continued = reduce(
            Some(suspended),
            &envelope(
                10,
                RuntimeCommittedEvent::ModelRequestStarted(ModelRequestStartedEvent {
                    cancellation_id: cancellation_id.clone(),
                }),
            ),
        )
        .expect("continued provider phase starts after exact suspension");
        assert_eq!(
            continued
                .style_execution
                .as_ref()
                .expect("execution")
                .generic_model_invocations
                .get(&cancellation_id)
                .expect("binding")
                .phases
                .len(),
            2
        );
        let completed = reduce(
            Some(siblings),
            &envelope(
                9,
                RuntimeCommittedEvent::ModelResponseCompleted(ModelResponseCompletedEvent {
                    cancellation_id: cancellation_id.clone(),
                    finish_reason: String::from("tool_calls"),
                    input_tokens: 3,
                    output_tokens: 5,
                    reasoning_tokens: 0,
                    estimated: false,
                    cost_micros: 0,
                }),
            ),
        )
        .expect("complete sibling batch");
        let phase = completed
            .style_execution
            .as_ref()
            .expect("execution")
            .generic_model_invocations
            .get(&cancellation_id)
            .expect("binding")
            .phases
            .last()
            .expect("phase");
        assert_eq!(
            phase
                .proposals
                .iter()
                .map(|proposal| proposal.call_id.as_str())
                .collect::<Vec<_>>(),
            vec!["call-1", "call-2"]
        );
        assert_eq!(phase.visible_text, "bounded");
        assert!(matches!(
            reduce(
                Some(completed.clone()),
                &envelope(
                    10,
                    RuntimeCommittedEvent::ModelToolCallProposed(proposal(
                        &cancellation_id,
                        "call-after-complete",
                    )),
                ),
            ),
            Err(SessionReducerError::InvalidModelExecutionEvidence)
        ));

        let cancelled = reduce(
            Some(with_text.clone()),
            &envelope(
                7,
                RuntimeCommittedEvent::ModelRequestCancelled(ModelRequestCancelledEvent {
                    cancellation_id: cancellation_id.clone(),
                }),
            ),
        )
        .expect("cancel exact phase");
        for event in [
            RuntimeCommittedEvent::ModelOutputDeltaObserved(ModelOutputDeltaObservedEvent {
                cancellation_id: cancellation_id.clone(),
                text: String::from("late"),
            }),
            RuntimeCommittedEvent::ModelResponseCompleted(ModelResponseCompletedEvent {
                cancellation_id: cancellation_id.clone(),
                finish_reason: String::from("stop"),
                input_tokens: 1,
                output_tokens: 1,
                reasoning_tokens: 0,
                estimated: false,
                cost_micros: 0,
            }),
        ] {
            assert!(matches!(
                reduce(Some(cancelled.clone()), &envelope(8, event)),
                Err(SessionReducerError::InvalidModelExecutionEvidence)
            ));
        }

        let failed = reduce(
            Some(with_text),
            &envelope(
                7,
                RuntimeCommittedEvent::ModelRequestFailed(ModelRequestFailedEvent {
                    code: String::from("provider_failed"),
                    message: String::from("redacted"),
                    retryable: false,
                }),
            ),
        )
        .expect("fail exact phase");
        assert!(matches!(
            reduce(
                Some(failed),
                &envelope(
                    8,
                    RuntimeCommittedEvent::ModelResponseCompleted(ModelResponseCompletedEvent {
                        cancellation_id,
                        finish_reason: String::from("stop"),
                        input_tokens: 1,
                        output_tokens: 1,
                        reasoning_tokens: 0,
                        estimated: false,
                        cost_micros: 0,
                    }),
                ),
            ),
            Err(SessionReducerError::InvalidModelExecutionEvidence)
        ));
    }

    #[test]
    fn generic_tool_completion_requires_exact_work_call_terminal_receipt() {
        let state = active_generic_effect_state(NodeKind::ToolExecutionGate);
        let completed = StyleNodeCompletedEvent {
            node_id: String::from("inspect-workspace"),
            attempt: 1,
            loop_iteration: 0,
            step: 1,
            result_reference: Some(String::from("tool:graph:inspect-workspace:1:0:1")),
            artifact_reference: None,
        };
        assert!(matches!(
            reduce(
                Some(state.clone()),
                &envelope(
                    4,
                    RuntimeCommittedEvent::StyleNodeCompleted(completed.clone())
                )
            ),
            Err(SessionReducerError::InvalidStyleExecutionTransition)
        ));

        let wrong = reduce(
            Some(state.clone()),
            &envelope(
                4,
                RuntimeCommittedEvent::ToolExecutionDispatched(ToolExecutionDispatchedEvent {
                    execution_id: String::from("wrong-execution"),
                    call_id: String::from("graph:other-node:1:0:1"),
                    action_digest: ContentHash::digest(b"wrong tool action"),
                }),
            ),
        )
        .and_then(|state| {
            reduce(
                Some(state),
                &envelope(
                    5,
                    RuntimeCommittedEvent::ToolExecutionCompleted(ToolExecutionCompletedEvent {
                        call_id: String::from("graph:other-node:1:0:1"),
                        result: serde_json::json!({"ok": true}),
                        artifact: None,
                        truncated: false,
                    }),
                ),
            )
        })
        .expect("unrelated terminal tool receipt");
        assert!(matches!(
            reduce(
                Some(wrong),
                &envelope(
                    6,
                    RuntimeCommittedEvent::StyleNodeCompleted(completed.clone())
                )
            ),
            Err(SessionReducerError::InvalidStyleExecutionTransition)
        ));

        let call_id = String::from("graph:inspect-workspace:1:0:1");
        let exact = reduce(
            Some(state),
            &envelope(
                4,
                RuntimeCommittedEvent::ToolExecutionDispatched(ToolExecutionDispatchedEvent {
                    execution_id: String::from("generic-tool-execution"),
                    call_id: call_id.clone(),
                    action_digest: ContentHash::digest(b"exact tool action"),
                }),
            ),
        )
        .and_then(|state| {
            reduce(
                Some(state),
                &envelope(
                    5,
                    RuntimeCommittedEvent::ToolExecutionCompleted(ToolExecutionCompletedEvent {
                        call_id,
                        result: serde_json::json!({"ok": true}),
                        artifact: None,
                        truncated: false,
                    }),
                ),
            )
        })
        .expect("exact terminal tool receipt");
        reduce(
            Some(exact),
            &envelope(6, RuntimeCommittedEvent::StyleNodeCompleted(completed)),
        )
        .expect("exact generic tool receipt authorizes completion");
    }

